from jsonb_to_recordset($q$[{"id": 9947, "materia": "adm", "nivel": 0, "enunciado": "A obrigação de divulgar os atos oficiais decorre do princípio da:", "opcoes": ["Publicidade", "Legalidade", "Impessoalidade", "Eficiência"], "explicacao": "Art. 37 da CF."}, {"id": 9948, "materia": "adm", "nivel": 0, "enunciado": "O servidor que atende todos os cidadãos sem favorecimento cumpre o princípio da:", "opcoes": ["Impessoalidade", "Publicidade", "Eficiência", "Hierarquia"], "explicacao": "Art. 37 da CF."}, {"id": 9949, "materia": "adm", "nivel": 0, "enunciado": "A investidura em cargo efetivo depende, em regra, de:", "opcoes": ["Aprovação em concurso público", "Indicação política do governador", "Entrevista com o chefe", "Sorteio público"], "explicacao": "Art. 37, II, da CF."}, {"id": 9950, "materia": "adm", "nivel": 0, "enunciado": "O agente que aplica uma multa de trânsito exerce o poder:", "opcoes": ["De polícia", "Disciplinar", "Regulamentar", "Hierárquico"], "explicacao": "Poder de limitar direitos em favor do interesse público."}, {"id": 9951, "materia": "adm", "nivel": 0, "enunciado": "O chefe que pune um servidor por falta funcional exerce o poder:", "opcoes": ["Disciplinar", "De polícia", "Regulamentar", "Normativo"], "explicacao": "Poder de apurar e punir infrações funcionais."}, {"id": 9952, "materia": "adm", "nivel": 0, "enunciado": "Dar ordens e rever atos dos subordinados decorre do poder:", "opcoes": ["Hierárquico", "De polícia", "Regulamentar", "Disciplinar"], "explicacao": "Organiza a relação de subordinação."}, {"id": 9953, "materia": "adm", "nivel": 0, "enunciado": "O prazo de validade do concurso público é de até:", "opcoes": ["2 anos, prorrogável uma vez", "5 anos, sem possibilidade de prorrogação", "1 ano, sem possibilidade de prorrogação", "4 anos, prorrogável duas vezes"], "explicacao": "Art. 37, III, da CF."}, {"id": 9954, "materia": "adm", "nivel": 0, "enunciado": "Um policial civil é exemplo de agente público:", "opcoes": ["Servidor público efetivo", "Agente político", "Particular em colaboração", "Empregado de estatal"], "explicacao": "Ocupa cargo efetivo, provido por concurso."}, {"id": 9955, "materia": "const", "nivel": 0, "enunciado": "Quanto à forma de Estado, o Brasil é uma:", "opcoes": ["Federação", "Confederação", "Monarquia", "Estado unitário"], "explicacao": "Art. 1º da CF: República Federativa."}, {"id": 9956, "materia": "const", "nivel": 0, "enunciado": "Nos estados, a apuração das infrações penais, exceto as militares, cabe à:", "opcoes": ["Polícia Civil", "Polícia Militar", "Polícia Federal", "Guarda Municipal"], "explicacao": "Art. 144, § 4º, da CF."}, {"id": 9957, "materia": "const", "nivel": 0, "enunciado": "O policiamento ostensivo e a preservação da ordem pública cabem à:", "opcoes": ["Polícia Militar", "Polícia Civil", "Polícia Federal", "Polícia Penal"], "explicacao": "Art. 144, § 5º, da CF."}, {"id": 9958, "materia": "const", "nivel": 0, "enunciado": "A Polícia Penal, incluída na Constituição em 2019, cuida da:", "opcoes": ["Segurança dos estabelecimentos penais", "Investigação de crimes comuns no estado", "Patrulha das rodovias federais", "Fiscalização das fronteiras"], "explicacao": "Art. 144, § 5º-A, da CF."}, {"id": 9959, "materia": "const", "nivel": 0, "enunciado": "Pela Constituição, a casa é:", "opcoes": ["Asilo inviolável do indivíduo", "Propriedade do Estado", "Livre para buscas policiais", "Inviolável apenas durante o dia"], "explicacao": "Art. 5º, XI, da CF."}, {"id": 9960, "materia": "const", "nivel": 0, "enunciado": "A Constituição garante que ninguém será considerado culpado até o:", "opcoes": ["Trânsito em julgado da sentença condenatória", "Recebimento da denúncia", "Indiciamento no inquérito", "Fim da audiência de custódia no fórum criminal"], "explicacao": "Art. 5º, LVII, da CF."}, {"id": 9961, "materia": "const", "nivel": 0, "enunciado": "Pela Constituição, não haverá juízo ou tribunal de:", "opcoes": ["Exceção", "Júri", "Recursos", "Pequenas causas"], "explicacao": "Art. 5º, XXXVII, da CF."}, {"id": 9962, "materia": "dh", "nivel": 0, "enunciado": "Pela Declaração Universal, toda pessoa tem direito à vida, à liberdade e à:", "opcoes": ["Segurança pessoal", "Riqueza", "Propriedade de terras", "Cidadania de qualquer país"], "explicacao": "Art. 3º da DUDH."}, {"id": 9963, "materia": "dh", "nivel": 0, "enunciado": "Pela Declaração Universal, ninguém será submetido a:", "opcoes": ["Tortura nem a tratamento cruel ou degradante", "Julgamento por tribunal independente e imparcial", "Prisão em flagrante delito", "Pagamento de tributos"], "explicacao": "Art. 5º da DUDH."}, {"id": 9964, "materia": "dh", "nivel": 0, "enunciado": "Dizer que os direitos humanos são indivisíveis significa que:", "opcoes": ["Devem ser garantidos juntos, sem hierarquia", "Só os direitos civis são obrigatórios para o Estado", "Podem ser divididos por classe social", "Valem apenas em parte do território"], "explicacao": "Direitos civis, políticos, sociais e culturais formam um todo."}, {"id": 9965, "materia": "igual", "nivel": 0, "enunciado": "A Lei 7.716/1989 é conhecida como:", "opcoes": ["Lei do Racismo", "Lei Maria da Penha", "Lei de Drogas", "Lei de Tortura"], "explicacao": "Define os crimes resultantes de preconceito de raça ou de cor."}, {"id": 9966, "materia": "inf", "nivel": 0, "enunciado": "Um endereço de e-mail é formado por nome do usuário, @ e:", "opcoes": ["Domínio", "Senha", "Porta", "Protocolo"], "explicacao": "Ex.: nome@dominio.com.br."}, {"id": 9967, "materia": "inf", "nivel": 0, "enunciado": "O antivírus serve para:", "opcoes": ["Detectar e remover programas maliciosos", "Acelerar a conexão com a internet e a rede", "Editar textos e planilhas", "Fazer cópias de segurança automáticas"], "explicacao": "Protege contra malware."}, {"id": 9968, "materia": "inf", "nivel": 0, "enunciado": "A extensão .pdf indica, em geral, um arquivo de:", "opcoes": ["Documento portátil", "Planilha", "Áudio", "Programa"], "explicacao": "PDF: Portable Document Format."}, {"id": 9969, "materia": "inf", "nivel": 0, "enunciado": "Qual dispositivo é usado para digitar textos no computador?", "opcoes": ["Teclado", "Monitor", "Impressora", "Caixa de som"], "explicacao": "É um dispositivo de entrada."}, {"id": 9970, "materia": "inf", "nivel": 0, "enunciado": "Para proteger uma conta, a senha mais segura é a que:", "opcoes": ["Longa e com letras, números e símbolos", "Usa a data de nascimento do usuário", "Repete a mesma senha em todos os sites", "Tem só quatro números em sequência"], "explicacao": "Senhas longas e variadas são mais difíceis de descobrir."}, {"id": 9971, "materia": "leg", "nivel": 0, "enunciado": "A Lei 11.343/2006 trata de:", "opcoes": ["Drogas", "Armas de fogo", "Violência doméstica", "Crimes hediondos"], "explicacao": "É a Lei de Drogas."}, {"id": 9972, "materia": "leg", "nivel": 0, "enunciado": "A Lei 10.826/2003 é conhecida como:", "opcoes": ["Estatuto do Desarmamento", "Lei de Drogas", "Estatuto da Pessoa Idosa", "Lei de Tortura"], "explicacao": "Trata de registro, posse e porte de armas."}, {"id": 9973, "materia": "leg", "nivel": 0, "enunciado": "Pela Lei de Drogas, quem é flagrado com droga para consumo pessoal:", "opcoes": ["Não é preso e recebe medidas como advertência", "É preso em flagrante e cumpre pena no regime fechado", "Paga fiança e responde por tráfico", "Responde por tráfico privilegiado"], "explicacao": "Art. 28 e art. 48, § 2º, da Lei 11.343/2006."}, {"id": 9974, "materia": "leg", "nivel": 0, "enunciado": "São formas de violência previstas na Lei Maria da Penha: física, psicológica, sexual, patrimonial e:", "opcoes": ["Moral", "Digital", "Econômica", "Religiosa"], "explicacao": "Art. 7º da Lei 11.340/2006."}, {"id": 9975, "materia": "leg", "nivel": 0, "enunciado": "Pelo CTB, o motorista que se recusa a fazer o teste do bafômetro:", "opcoes": ["Tem as mesmas penalidades administrativas de quem bebeu", "Não sofre nenhuma penalidade, pois ninguém produz prova contra si", "É preso em flagrante automaticamente por crime de trânsito previsto no CTB", "Recebe apenas uma advertência verbal do agente"], "explicacao": "Art. 165-A do CTB."}, {"id": 9976, "materia": "leg", "nivel": 0, "enunciado": "A Lei dos Crimes Hediondos é a:", "opcoes": ["Lei 8.072/1990", "Lei 9.455/1997", "Lei 7.716/1989", "Lei 9.099/1995"], "explicacao": "Lei 8.072/1990."}, {"id": 9977, "materia": "leg", "nivel": 0, "enunciado": "Pelo ECA, o adolescente que pratica ato infracional pode receber:", "opcoes": ["Medidas socioeducativas", "Pena de reclusão", "Pena de detenção", "Prisão simples"], "explicacao": "Art. 112 do ECA."}, {"id": 9978, "materia": "leg", "nivel": 0, "enunciado": "Pelo CTB, dirigir sob influência de álcool é infração:", "opcoes": ["Gravíssima", "Leve", "Média", "Grave"], "explicacao": "Art. 165 do CTB, com multa multiplicada por 10."}, {"id": 9979, "materia": "leg", "nivel": 0, "enunciado": "Um motorista bebe, dirige e é parado numa blitz com 0,5 mg de álcool por litro de ar. Ele comete:", "opcoes": ["Crime de embriaguez ao volante", "Apenas infração de trânsito gravíssima", "Contravenção penal", "Fato atípico"], "explicacao": "Art. 306 do CTB: 0,3 mg/L ou mais configura crime."}, {"id": 9980, "materia": "leg", "nivel": 0, "enunciado": "Um homem agride a esposa em casa. O caso deve seguir a:", "opcoes": ["Lei Maria da Penha", "Lei 9.099/1995", "Lei de Tortura", "Lei dos Juizados Cíveis"], "explicacao": "Violência doméstica e familiar contra a mulher."}, {"id": 9981, "materia": "leg", "nivel": 0, "enunciado": "Abandonar um cachorro e deixá-lo sem comida por dias pode configurar:", "opcoes": ["Crime de maus-tratos a animais", "Apenas infração civil, sujeita a multa", "Contravenção penal", "Fato atípico"], "explicacao": "Art. 32 da Lei 9.605/1998."}, {"id": 9982, "materia": "ml", "nivel": 0, "enunciado": "A medicina legal auxilia principalmente:", "opcoes": ["A Justiça, com conhecimentos médicos", "Os hospitais, no atendimento", "As escolas, no ensino", "Os bancos, nas análises de crédito pessoal"], "explicacao": "Também chamada de medicina forense."}, {"id": 9983, "materia": "ml", "nivel": 0, "enunciado": "O Instituto Médico Legal (IML) realiza, entre outros:", "opcoes": ["Necropsias e exames de lesões", "Cirurgias de emergência e partos", "Campanhas de vacinação", "Exames admissionais"], "explicacao": "Exames periciais para a Justiça."}, {"id": 9984, "materia": "ml", "nivel": 0, "enunciado": "A rigidez cadavérica também é chamada de:", "opcoes": ["Rigor mortis", "Livor mortis", "Algor mortis", "Autólise"], "explicacao": "Endurecimento dos músculos após a morte."}, {"id": 9985, "materia": "ml", "nivel": 0, "enunciado": "O resfriamento do corpo após a morte é o:", "opcoes": ["Algor mortis", "Rigor mortis", "Livor mortis", "Saponificação"], "explicacao": "Perda gradual de calor."}, {"id": 9986, "materia": "ml", "nivel": 0, "enunciado": "As manchas arroxeadas nas partes mais baixas do cadáver são os:", "opcoes": ["Livores", "Hematomas", "Equimoses", "Rigores"], "explicacao": "O sangue desce por gravidade."}, {"id": 9987, "materia": "ml", "nivel": 0, "enunciado": "A identificação pelas impressões digitais chama-se:", "opcoes": ["Datiloscopia", "Odontologia legal", "Antropometria", "Balística"], "explicacao": "Base do sistema de Vucetich."}, {"id": 9988, "materia": "pcd", "nivel": 0, "enunciado": "A Lei Brasileira de Inclusão (LBI) é a Lei:", "opcoes": ["13.146/2015", "10.098/2000", "7.853/1989", "12.764/2012"], "explicacao": "Estatuto da Pessoa com Deficiência."}, {"id": 9989, "materia": "pcd", "nivel": 0, "enunciado": "A Libras foi reconhecida como meio legal de comunicação pela Lei:", "opcoes": ["10.436/2002", "13.146/2015", "10.048/2000", "8.213/1991"], "explicacao": "Lei 10.436/2002."}, {"id": 9990, "materia": "pcd", "nivel": 0, "enunciado": "A acessibilidade busca garantir à pessoa com deficiência:", "opcoes": ["Autonomia e segurança no uso de espaços e serviços", "Isenção de impostos sobre qualquer produto", "Prioridade para votar antes dos demais eleitores, em qualquer seção", "Aposentadoria imediata, sem contribuição"], "explicacao": "Art. 3º, I, da LBI."}, {"id": 9991, "materia": "pen", "nivel": 0, "enunciado": "Depois de uma discussão, Carla manda mensagem à vizinha dizendo que vai matá-la. Carla comete:", "opcoes": ["Ameaça", "Injúria", "Constrangimento ilegal", "Perseguição (stalking)"], "explicacao": "Art. 147 do CP: ameaçar alguém de causar mal injusto e grave."}, {"id": 9992, "materia": "pen", "nivel": 0, "enunciado": "Chamar alguém de “ladrão” em público, sem apontar um fato concreto, é crime de:", "opcoes": ["Injúria", "Calúnia", "Difamação", "Desacato"], "explicacao": "Art. 140 do CP: ofende a dignidade sem imputar fato determinado."}, {"id": 9993, "materia": "pen", "nivel": 0, "enunciado": "Espalhar no bairro que o vizinho chega bêbado ao trabalho todo dia, fato ofensivo mas não criminoso, é:", "opcoes": ["Difamação", "Calúnia", "Injúria", "Ameaça"], "explicacao": "Art. 139 do CP: imputar fato ofensivo à reputação."}, {"id": 9994, "materia": "pen", "nivel": 0, "enunciado": "Um homem quebra de propósito o vidro do carro do vizinho, sem levar nada. Ele comete:", "opcoes": ["Dano", "Furto", "Roubo", "Violação de domicílio"], "explicacao": "Art. 163 do CP: destruir, inutilizar ou deteriorar coisa alheia."}, {"id": 9995, "materia": "pen", "nivel": 0, "enunciado": "Exigir, em razão da função pública, vantagem indevida é crime de:", "opcoes": ["Concussão", "Corrupção passiva", "Peculato", "Extorsão"], "explicacao": "Art. 316 do CP. Na corrupção passiva, o servidor solicita ou recebe; na concussão, exige."}, {"id": 9996, "materia": "pen", "nivel": 0, "enunciado": "Oferecer dinheiro a um policial para não ser autuado é crime de:", "opcoes": ["Corrupção ativa", "Corrupção passiva", "Concussão", "Tráfico de influência"], "explicacao": "Art. 333 do CP: oferecer ou prometer vantagem indevida a funcionário público."}, {"id": 9997, "materia": "pen", "nivel": 0, "enunciado": "Xingar um policial em serviço durante a abordagem é crime de:", "opcoes": ["Desacato", "Desobediência", "Resistência", "Ameaça"], "explicacao": "Art. 331 do CP: desacatar funcionário público no exercício da função."}, {"id": 9998, "materia": "pen", "nivel": 0, "enunciado": "Matar alguém sem querer, por descuido ao limpar uma arma, é homicídio:", "opcoes": ["Culposo", "Doloso", "Qualificado", "Privilegiado"], "explicacao": "Art. 121, § 3º, do CP."}, {"id": 9999, "materia": "pen", "nivel": 0, "enunciado": "Pedro aponta uma faca para um pedestre e leva o celular dele. Pedro comete:", "opcoes": ["Roubo", "Furto qualificado", "Extorsão", "Latrocínio"], "explicacao": "Art. 157 do CP: subtração com grave ameaça à pessoa."}, {"id": 10000, "materia": "pen", "nivel": 0, "enunciado": "Vender um carro alheio como se fosse próprio, enganando o comprador, configura:", "opcoes": ["Estelionato", "Furto", "Apropriação indébita", "Receptação"], "explicacao": "Art. 171, § 2º, I, do CP: disposição de coisa alheia como própria."}, {"id": 10001, "materia": "pen", "nivel": 0, "enunciado": "Comprar um celular sabendo que ele foi roubado é crime de:", "opcoes": ["Receptação", "Favorecimento real", "Furto", "Roubo"], "explicacao": "Art. 180 do CP."}, {"id": 10002, "materia": "pen", "nivel": 0, "enunciado": "Durante uma briga de bar, Léo dá um soco em Caio, que fica com um corte leve no lábio e é liberado no mesmo dia. Léo comete:", "opcoes": ["Lesão corporal leve", "Lesão corporal grave", "Vias de fato", "Tentativa de homicídio"], "explicacao": "Art. 129, caput, do CP: houve ofensa à integridade física."}, {"id": 10003, "materia": "pen", "nivel": 0, "enunciado": "Sem que a dona perceba, Bruno tira a carteira da bolsa dela no ônibus. Bruno comete:", "opcoes": ["Furto", "Roubo", "Estelionato", "Apropriação indébita"], "explicacao": "Subtração sem violência nem grave ameaça: art. 155 do CP."}, {"id": 10004, "materia": "pen", "nivel": 0, "enunciado": "Jorge recebe por engano um Pix de R$ 500 e, sabendo do erro, gasta o dinheiro em vez de devolvê-lo. Ele comete:", "opcoes": ["Apropriação de coisa havida por erro", "Furto mediante fraude eletrônica (Pix)", "Estelionato", "Receptação"], "explicacao": "Art. 169 do CP."}, {"id": 10005, "materia": "port", "nivel": 0, "enunciado": "Em “Os policiais chegaram cedo”, o sujeito é:", "opcoes": ["Os policiais", "Cedo", "Chegaram", "Oculto"], "explicacao": "Quem chegou? Os policiais."}, {"id": 10006, "materia": "port", "nivel": 0, "enunciado": "A palavra “rápido” leva acento porque é:", "opcoes": ["Proparoxítona", "Oxítona", "Paroxítona", "Monossílaba"], "explicacao": "Todas as proparoxítonas são acentuadas."}, {"id": 10007, "materia": "port", "nivel": 0, "enunciado": "O sinônimo de “ileso” é:", "opcoes": ["Sem ferimentos", "Ferido", "Preso", "Suspeito"], "explicacao": "Ileso: que não sofreu lesão."}, {"id": 10008, "materia": "port", "nivel": 0, "enunciado": "Qual palavra está escrita corretamente?", "opcoes": ["Análise", "Análize", "Analize", "Anályse"], "explicacao": "Análise, com s."}, {"id": 10009, "materia": "port", "nivel": 0, "enunciado": "Qual palavra está escrita corretamente?", "opcoes": ["Investigação", "Investigassão", "Envestigação", "Investigaçao"], "explicacao": "Investigação, com ç e til."}, {"id": 10010, "materia": "ppen", "nivel": 0, "enunciado": "Após a prisão em flagrante, o delegado deve comunicá-la imediatamente ao juiz, ao Ministério Público e:", "opcoes": ["À família do preso ou à pessoa que ele indicar", "Ao prefeito da cidade onde ocorreu", "À imprensa local, para dar publicidade ao caso", "Ao empregador do preso, se houver"], "explicacao": "Art. 306 do CPP e art. 5º, LXII, da CF."}, {"id": 10011, "materia": "ppen", "nivel": 0, "enunciado": "A nota de culpa entregue ao preso em flagrante informa:", "opcoes": ["O motivo da prisão e os nomes do condutor e testemunhas", "A pena que ele deve receber ao final do processo criminal", "O nome do juiz que vai julgar o caso", "O valor da fiança já fixado pelo juiz"], "explicacao": "Art. 306, § 2º, do CPP."}, {"id": 10012, "materia": "ppen", "nivel": 0, "enunciado": "O mandado de prisão é expedido pelo:", "opcoes": ["Juiz competente", "Delegado de polícia", "Promotor de justiça", "Comandante da PM"], "explicacao": "Art. 5º, LXI, da CF, salvo flagrante e crimes militares."}, {"id": 10013, "materia": "ppen", "nivel": 0, "enunciado": "Na ação penal privada, a peça acusatória é a:", "opcoes": ["Queixa-crime", "Denúncia", "Notícia-crime", "Representação"], "explicacao": "Art. 30 do CPP."}, {"id": 10014, "materia": "ppen", "nivel": 0, "enunciado": "Nas infrações de menor potencial ofensivo, em vez do auto de prisão, a polícia lavra:", "opcoes": ["Termo circunstanciado", "Boletim de ocorrência", "Auto de apreensão", "Relatório final"], "explicacao": "Art. 69 da Lei 9.099/1995."}, {"id": 10015, "materia": "ppen", "nivel": 0, "enunciado": "O exame de corpo de delito pode ser feito:", "opcoes": ["Em qualquer dia e a qualquer hora", "Só em dias úteis", "Só durante o dia", "Só com ordem prévia e escrita do juiz"], "explicacao": "Art. 161 do CPP."}, {"id": 10016, "materia": "ppen", "nivel": 0, "enunciado": "No Tribunal do Júri, quem decide se o réu é culpado são os:", "opcoes": ["Jurados", "Juízes de direito", "Promotores de justiça", "Desembargadores"], "explicacao": "Conselho de Sentença, formado por cidadãos."}, {"id": 10017, "materia": "ppen", "nivel": 0, "enunciado": "O Tribunal do Júri julga os crimes:", "opcoes": ["Dolosos contra a vida", "Culposos de trânsito", "Contra o patrimônio", "Contra a administração"], "explicacao": "Art. 5º, XXXVIII, d, da CF."}, {"id": 10018, "materia": "ppen", "nivel": 0, "enunciado": "Sem consentimento do morador e fora de flagrante, a busca na casa depende de:", "opcoes": ["Mandado judicial, cumprido durante o dia", "Ordem verbal do delegado de polícia de plantão", "Autorização por escrito do promotor", "Pedido formal da vítima do crime"], "explicacao": "Art. 5º, XI, da CF."}, {"id": 10019, "materia": "ppen", "nivel": 0, "enunciado": "O boletim de ocorrência é registrado, em regra, na:", "opcoes": ["Delegacia de polícia", "Vara criminal", "Promotoria", "Defensoria"], "explicacao": "É o registro da notícia do fato à polícia."}, {"id": 10020, "materia": "ppen", "nivel": 0, "enunciado": "Um policial vê um homem quebrando o vidro de um carro para furtá-lo e o prende na hora. Essa prisão é em flagrante:", "opcoes": ["Próprio", "Impróprio", "Presumido", "Diferido"], "explicacao": "Art. 302, I, do CPP: está cometendo a infração."}, {"id": 10021, "materia": "ppen", "nivel": 0, "enunciado": "O documento que registra a apreensão de objetos ligados ao crime é o:", "opcoes": ["Auto de apreensão", "Boletim de ocorrência", "Mandado de busca", "Termo de declarações"], "explicacao": "Formaliza a apreensão feita pela polícia."}, {"id": 10022, "materia": "ppen", "nivel": 0, "enunciado": "Qualquer pessoa do povo, diante de um crime em flagrante:", "opcoes": ["Pode prender o autor", "Deve prendê-lo, sob pena de crime", "Nunca pode prender", "Só pode prender se for maior de 21 anos"], "explicacao": "Art. 301 do CPP: faculdade para o cidadão, dever para a polícia."}, {"id": 10023, "materia": "rl", "nivel": 0, "enunciado": "A negação de “Está chovendo” é:", "opcoes": ["Não está chovendo", "Está fazendo sol", "Vai chover mais tarde", "Choveu ontem à noite"], "explicacao": "Basta negar a afirmação."}, {"id": 10024, "materia": "rl", "nivel": 0, "enunciado": "Se todo cão late e Rex é um cão, então:", "opcoes": ["Rex late", "Rex não late", "Todo animal que late é cão", "Nada se pode concluir"], "explicacao": "Rex pertence ao grupo dos cães, e todos latem."}, {"id": 10025, "materia": "rl", "nivel": 0, "enunciado": "Um agente recebe R$ 4.000 e gasta 25% com aluguel. Quanto sobra?", "opcoes": ["R$ 3.000", "R$ 1.000", "R$ 3.250", "R$ 2.500"], "explicacao": "25% de 4.000 = 1.000; sobram 3.000."}, {"id": 10026, "materia": "adm", "nivel": 1, "enunciado": "O atributo que permite à Administração executar o ato sem ordem judicial é a:", "opcoes": ["Autoexecutoriedade", "Presunção de legitimidade", "Tipicidade", "Imperatividade"], "explicacao": "Ex.: demolição de obra que ameaça ruir."}, {"id": 10027, "materia": "adm", "nivel": 1, "enunciado": "A revogação de ato válido, por conveniência e oportunidade, produz efeitos:", "opcoes": ["Só para o futuro (ex nunc)", "Retroativos (ex tunc)", "Só após decisão judicial definitiva", "Para o passado e o futuro"], "explicacao": "Respeitam-se os direitos adquiridos."}, {"id": 10028, "materia": "adm", "nivel": 1, "enunciado": "A Administração pode anular seus atos ilegais e revogar os inconvenientes, conforme a:", "opcoes": ["Súmula 473 do STF", "Súmula Vinculante 13", "Súmula 7 do STJ", "Súmula Vinculante 11"], "explicacao": "Princípio da autotutela."}, {"id": 10029, "materia": "adm", "nivel": 1, "enunciado": "Salvo má-fé, a Administração pode anular atos que favorecem os destinatários em até:", "opcoes": ["5 anos", "10 anos", "2 anos", "20 anos"], "explicacao": "Art. 54 da Lei 9.784/1999."}, {"id": 10030, "materia": "adm", "nivel": 1, "enunciado": "O servidor estável pode perder o cargo, entre outros casos, por:", "opcoes": ["Sentença judicial transitada em julgado", "Decisão verbal do chefe imediato do setor", "Mudança de governo", "Pedido de outro servidor"], "explicacao": "Art. 41, § 1º, da CF."}, {"id": 10031, "materia": "adm", "nivel": 1, "enunciado": "Pela Lei 8.112/1990, o servidor tem prazo de quantos dias para tomar posse?", "opcoes": ["30 dias", "15 dias", "45 dias", "60 dias"], "explicacao": "Art. 13, § 1º, da Lei 8.112/1990."}, {"id": 10032, "materia": "adm", "nivel": 1, "enunciado": "Pela Lei 8.112/1990, a vacância do cargo pode ocorrer por:", "opcoes": ["Exoneração, demissão, promoção, aposentadoria ou falecimento, entre outros", "Nomeação, posse e exercício em outro cargo do mesmo órgão, entre outros casos", "Remoção e redistribuição", "Férias e licenças"], "explicacao": "Art. 33 da Lei 8.112/1990."}, {"id": 10033, "materia": "const", "nivel": 1, "enunciado": "Pela Constituição, a prática do racismo é crime:", "opcoes": ["Inafiançável e imprescritível, com reclusão", "Afiançável e prescritível, sujeito a detenção", "De menor potencial ofensivo, sujeito a multa", "Inafiançável, mas prescritível em 20 anos"], "explicacao": "Art. 5º, XLII, da CF."}, {"id": 10034, "materia": "const", "nivel": 1, "enunciado": "Nenhuma pena passará da pessoa do condenado, mas a obrigação de reparar o dano pode se estender aos:", "opcoes": ["Sucessores, até o valor do patrimônio herdado", "Sucessores, sem nenhum limite de valor", "Parentes que moravam com o condenado na época", "Sócios e colegas de trabalho do condenado"], "explicacao": "Art. 5º, XLV, da CF."}, {"id": 10035, "materia": "const", "nivel": 1, "enunciado": "Entre os direitos do preso, a Constituição garante o de:", "opcoes": ["Permanecer calado", "Escolher o juiz", "Recusar a prisão", "Fixar a fiança"], "explicacao": "Art. 5º, LXIII, da CF."}, {"id": 10036, "materia": "const", "nivel": 1, "enunciado": "A prisão de qualquer pessoa e o local onde se encontra serão comunicados imediatamente:", "opcoes": ["Ao juiz e à família do preso ou a quem ele indicar", "Ao prefeito e ao governador do estado, por ofício", "À imprensa e ao empregador do preso, no mesmo dia", "Apenas ao Ministério Público, em sigilo"], "explicacao": "Art. 5º, LXII, da CF."}, {"id": 10037, "materia": "const", "nivel": 1, "enunciado": "O civilmente identificado não será submetido a identificação criminal, salvo:", "opcoes": ["Nas hipóteses previstas em lei", "Se o delegado entender necessário", "Em qualquer prisão em flagrante", "Se for estrangeiro"], "explicacao": "Art. 5º, LVIII, da CF e Lei 12.037/2009."}, {"id": 10038, "materia": "const", "nivel": 1, "enunciado": "O habeas data serve para:", "opcoes": ["Conhecer ou corrigir dados pessoais em registros públicos", "Proteger a liberdade de locomoção contra prisão ilegal", "Proteger direito líquido e certo contra ato de autoridade pública", "Anular ato que lese o patrimônio público"], "explicacao": "Art. 5º, LXXII, da CF."}, {"id": 10039, "materia": "const", "nivel": 1, "enunciado": "O mandado de segurança protege direito líquido e certo não amparado por:", "opcoes": ["Habeas corpus ou habeas data", "Ação popular", "Mandado de injunção ou ação popular", "Ação civil pública"], "explicacao": "Art. 5º, LXIX, da CF."}, {"id": 10040, "materia": "const", "nivel": 1, "enunciado": "Pela Constituição, a instituição do júri tem como uma de suas garantias:", "opcoes": ["A soberania dos veredictos", "O voto aberto dos jurados", "O julgamento pelo juiz togado", "A presença obrigatória da imprensa"], "explicacao": "Art. 5º, XXXVIII, da CF."}, {"id": 10041, "materia": "dh", "nivel": 1, "enunciado": "O Brasil reconheceu a competência da Corte Interamericana para julgar casos contra o país em:", "opcoes": ["1998", "1988", "1992", "2004"], "explicacao": "Decreto Legislativo 89/1998."}, {"id": 10042, "materia": "dh", "nivel": 1, "enunciado": "As Regras de Mandela, da ONU, tratam de:", "opcoes": ["Tratamento de pessoas presas", "Direitos das mulheres no trabalho", "Proteção de refugiados", "Trabalho infantil"], "explicacao": "Regras Mínimas para o Tratamento de Reclusos."}, {"id": 10043, "materia": "dh", "nivel": 1, "enunciado": "Pela Convenção Americana, a pena não pode passar da pessoa do:", "opcoes": ["Delinquente", "Juiz", "Defensor", "Promotor"], "explicacao": "Art. 5.3 da Convenção Americana."}, {"id": 10044, "materia": "dh", "nivel": 1, "enunciado": "Pela Convenção Americana, os menores processados devem ser separados dos:", "opcoes": ["Adultos", "Estrangeiros", "Primários", "Idosos"], "explicacao": "Art. 5.5 da Convenção Americana."}, {"id": 10045, "materia": "dh", "nivel": 1, "enunciado": "Pela Convenção Americana, as penas privativas de liberdade têm como finalidade essencial a:", "opcoes": ["A reforma e a readaptação social", "A vingança da sociedade contra o crime", "Arrecadação de multas pelo Estado", "Exclusão definitiva do condenado"], "explicacao": "Art. 5.6 da Convenção Americana."}, {"id": 10046, "materia": "igual", "nivel": 1, "enunciado": "A Lei 12.711/2012 trata de:", "opcoes": ["Cotas nas universidades e institutos federais", "Cotas em concursos do Judiciário e do Ministério Público", "Crimes de preconceito racial", "Terras de comunidades quilombolas"], "explicacao": "Lei de Cotas no ensino superior federal."}, {"id": 10047, "materia": "igual", "nivel": 1, "enunciado": "Desde a Lei 14.532/2023, a injúria racial está tipificada:", "opcoes": ["Na Lei 7.716/1989, equiparada ao racismo", "No Código Penal, como injúria simples, sem aumento", "No Estatuto da Igualdade Racial", "Na Lei das Contravenções Penais"], "explicacao": "Art. 2º-A da Lei 7.716/1989."}, {"id": 10048, "materia": "igual", "nivel": 1, "enunciado": "O dia 20 de novembro, feriado nacional desde 2023, é o Dia:", "opcoes": ["Nacional de Zumbi e da Consciência Negra", "da Abolição da Escravatura", "dos Povos Indígenas", "Internacional da Igualdade Racial e da Paz"], "explicacao": "Lei 14.759/2023."}, {"id": 10049, "materia": "igual", "nivel": 1, "enunciado": "Pela Lei 7.716/1989, recusar atendimento em hotel por preconceito de raça é:", "opcoes": ["Crime", "Infração apenas civil", "Contravenção penal", "Fato atípico"], "explicacao": "Art. 7º da Lei 7.716/1989."}, {"id": 10050, "materia": "inf", "nivel": 1, "enunciado": "O phishing é uma técnica para:", "opcoes": ["Enganar o usuário e obter seus dados", "Acelerar o computador", "Criptografar arquivos com autorização", "Fazer backup automático"], "explicacao": "Usa e-mails e sites falsos."}, {"id": 10051, "materia": "inf", "nivel": 1, "enunciado": "O firewall serve para:", "opcoes": ["Controlar o tráfego da rede e barrar acessos indevidos", "Remover vírus de arquivos que já foram infectados no computador", "Editar imagens e vídeos", "Aumentar a memória RAM"], "explicacao": "Filtra conexões de entrada e saída."}, {"id": 10052, "materia": "inf", "nivel": 1, "enunciado": "No Excel, a fórmula =SOMA(A1:A3) soma:", "opcoes": ["A1, A2 e A3", "Só A1 e A3", "De A1 até A30", "A1 três vezes"], "explicacao": "Os dois-pontos indicam intervalo."}, {"id": 10053, "materia": "inf", "nivel": 1, "enunciado": "O protocolo HTTPS indica que a conexão é:", "opcoes": ["Criptografada", "Mais rápida", "Feita sem internet", "Usada só para e-mail"], "explicacao": "O S vem de seguro (TLS)."}, {"id": 10054, "materia": "inf", "nivel": 1, "enunciado": "A memória RAM é:", "opcoes": ["Volátil: perde os dados ao desligar", "Permanente: guarda os dados para sempre", "Um tipo de pen drive", "Um dispositivo de saída"], "explicacao": "Guarda dados temporários em uso."}, {"id": 10055, "materia": "inf", "nivel": 1, "enunciado": "O backup serve principalmente para:", "opcoes": ["Recuperar dados em caso de perda", "Acelerar a internet", "Bloquear invasões", "Apagar arquivos antigos e temporários"], "explicacao": "É a cópia de segurança dos dados."}, {"id": 10056, "materia": "leg", "nivel": 1, "enunciado": "No tráfico privilegiado, a pena pode ser reduzida de:", "opcoes": ["Um sexto a dois terços", "Um terço à metade", "Metade a dois terços", "Um sexto a um terço"], "explicacao": "Art. 33, § 4º, da Lei 11.343/2006."}, {"id": 10057, "materia": "leg", "nivel": 1, "enunciado": "Para ter direito ao tráfico privilegiado, o agente deve ser:", "opcoes": ["Primário, de bons antecedentes, sem ligação com o crime organizado", "Reincidente, mas flagrado com pequena quantidade de droga para venda", "Primário, ainda que integre organização criminosa", "Maior de 70 anos ou menor de 21 na data do fato"], "explicacao": "Art. 33, § 4º, da Lei 11.343/2006."}, {"id": 10058, "materia": "leg", "nivel": 1, "enunciado": "Segundo o STF e a Lei 13.964/2019, o tráfico privilegiado:", "opcoes": ["Não é crime hediondo", "É crime hediondo", "É contravenção penal", "É de menor potencial ofensivo"], "explicacao": "Art. 112, § 5º, da LEP."}, {"id": 10059, "materia": "leg", "nivel": 1, "enunciado": "A associação para o tráfico (art. 35 da Lei de Drogas) exige:", "opcoes": ["Duas ou mais pessoas, de forma estável", "Quatro ou mais pessoas, com divisão de tarefas", "Três ou mais pessoas, armadas", "Uma única pessoa, com reiteração"], "explicacao": "Art. 35 da Lei 11.343/2006."}, {"id": 10060, "materia": "leg", "nivel": 1, "enunciado": "Manter em casa arma de fogo de uso permitido sem registro é:", "opcoes": ["Posse irregular de arma de fogo de uso permitido", "Porte ilegal de arma de fogo de uso permitido, sempre", "Comércio ilegal de arma de fogo", "Fato atípico, por estar dentro de casa"], "explicacao": "Art. 12 da Lei 10.826/2003."}, {"id": 10061, "materia": "leg", "nivel": 1, "enunciado": "A pena da posse irregular de arma de fogo de uso permitido é de:", "opcoes": ["Detenção de 1 a 3 anos e multa", "Reclusão de 2 a 4 anos e multa", "Reclusão de 3 a 6 anos e multa", "Detenção de 6 meses a 1 ano"], "explicacao": "Art. 12 da Lei 10.826/2003."}, {"id": 10062, "materia": "leg", "nivel": 1, "enunciado": "Aos crimes de violência doméstica contra a mulher:", "opcoes": ["Não se aplica a Lei 9.099/1995", "Aplica-se a transação penal", "Aplica-se sempre o sursis processual", "Aplica-se só a pena de cesta básica"], "explicacao": "Art. 41 da Lei 11.340/2006."}, {"id": 10063, "materia": "leg", "nivel": 1, "enunciado": "Nos casos de violência doméstica contra a mulher, é vedada a pena de:", "opcoes": ["Cesta básica ou multa isolada", "Prisão em regime fechado", "Prestação de serviços à comunidade", "Limitação de fim de semana"], "explicacao": "Art. 17 da Lei 11.340/2006."}, {"id": 10064, "materia": "leg", "nivel": 1, "enunciado": "Submeter pessoa presa a sofrimento físico ou mental por ato não previsto em lei é:", "opcoes": ["Tortura", "Maus-tratos", "Lesão corporal", "Constrangimento ilegal"], "explicacao": "Art. 1º, § 1º, da Lei 9.455/1997."}, {"id": 10065, "materia": "leg", "nivel": 1, "enunciado": "Pela Lei Maria da Penha, a violência doméstica independe de:", "opcoes": ["Orientação sexual", "Relação íntima de afeto", "Ambiente doméstico", "Gênero da vítima"], "explicacao": "Art. 5º, parágrafo único, da Lei 11.340/2006."}, {"id": 10066, "materia": "leg", "nivel": 1, "enunciado": "Pela Lei Maria da Penha, a vítima só pode renunciar à representação:", "opcoes": ["Perante o juiz, em audiência própria", "Na delegacia, em qualquer momento do inquérito", "Por escrito ao promotor", "Depois da sentença"], "explicacao": "Art. 16 da Lei 11.340/2006."}, {"id": 10067, "materia": "leg", "nivel": 1, "enunciado": "Pelo ECA, vender bebida alcoólica a adolescente é:", "opcoes": ["Crime", "Apenas infração administrativa", "Contravenção penal", "Fato atípico"], "explicacao": "Art. 243 do ECA."}, {"id": 10068, "materia": "leg", "nivel": 1, "enunciado": "Pelo ECA, a criança ou o adolescente só pode ser privado de liberdade em flagrante de ato infracional ou por:", "opcoes": ["Ordem escrita e fundamentada do juiz", "Ordem do Conselho Tutelar, por escrito", "Pedido dos pais", "Decisão do diretor da escola"], "explicacao": "Art. 106 do ECA."}, {"id": 10069, "materia": "ml", "nivel": 1, "enunciado": "A equimose é:", "opcoes": ["Mancha roxa por sangue extravasado", "Corte de bordas regulares e lisas na pele", "Fratura do osso sem ferida", "Queimadura causada pelo frio"], "explicacao": "Popular “roxo”."}, {"id": 10070, "materia": "ml", "nivel": 1, "enunciado": "O hematoma é:", "opcoes": ["Coleção de sangue que forma relevo", "Mancha superficial na pele, sem relevo", "Perfuração da pele", "Ferida infectada"], "explicacao": "Sangue acumulado em cavidade formada."}, {"id": 10071, "materia": "ml", "nivel": 1, "enunciado": "O machado produz, em regra, ferida:", "opcoes": ["Cortocontusa", "Incisa", "Perfurante", "Perfurocontusa"], "explicacao": "Corta e contunde pelo peso."}, {"id": 10072, "materia": "ml", "nivel": 1, "enunciado": "A agulha produz ferida:", "opcoes": ["Punctória", "Incisa", "Contusa", "Cortocontusa"], "explicacao": "Instrumento perfurante."}, {"id": 10073, "materia": "ml", "nivel": 1, "enunciado": "A lesão causada por instrumento contundente, como um pedaço de madeira, chama-se ferida:", "opcoes": ["Contusa", "Incisa", "Perfurante", "Perfuroincisa"], "explicacao": "Bordas irregulares e pontes de tecido."}, {"id": 10074, "materia": "ml", "nivel": 1, "enunciado": "O exame que verifica sinais de embriaguez em motorista é feito, entre outros meios, pelo:", "opcoes": ["Etilômetro (bafômetro)", "Eletrocardiograma", "Raio X", "Exame de vista"], "explicacao": "Também por exame de sangue ou clínico."}, {"id": 10075, "materia": "pcd", "nivel": 1, "enunciado": "A Lei 12.764/2012 instituiu a política de proteção dos direitos da pessoa com:", "opcoes": ["Transtorno do espectro autista", "Deficiência visual", "Deficiência auditiva", "Mobilidade reduzida permanente"], "explicacao": "Lei Berenice Piana."}, {"id": 10076, "materia": "pcd", "nivel": 1, "enunciado": "Pela LBI, a pessoa com deficiência tem direito a:", "opcoes": ["Atendimento prioritário", "Isenção de todos os tributos", "Aposentadoria aos 40 anos", "Dispensa de documento de identidade"], "explicacao": "Art. 9º da LBI."}, {"id": 10077, "materia": "pcd", "nivel": 1, "enunciado": "Pela Lei 11.126/2005, o cão-guia pode acompanhar a pessoa com deficiência visual:", "opcoes": ["Em locais públicos e privados de uso coletivo", "Apenas em parques, praças e repartições públicas", "Só em veículos particulares", "Somente dentro de casa"], "explicacao": "Inclusive em transportes."}, {"id": 10078, "materia": "pen", "nivel": 1, "enunciado": "O furto praticado durante o repouso noturno tem a pena:", "opcoes": ["Aumentada de um terço", "Aumentada da metade", "Aplicada em dobro", "Igual à do furto simples"], "explicacao": "Art. 155, § 1º, do CP."}, {"id": 10079, "materia": "pen", "nivel": 1, "enunciado": "É qualificadora do furto, entre outras:", "opcoes": ["O rompimento de obstáculo à subtração", "O repouso noturno da vítima", "O pequeno valor da coisa furtada", "A primariedade do autor e o pequeno valor"], "explicacao": "Art. 155, § 4º, I, do CP. O repouso noturno é causa de aumento, não qualificadora."}, {"id": 10080, "materia": "pen", "nivel": 1, "enunciado": "O furto privilegiado, com pena reduzida ou só de multa, exige que:", "opcoes": ["Autor primário e coisa de pequeno valor", "O crime aconteça de dia e sem testemunhas", "A vítima perdoe o autor depois do fato", "O autor devolva a coisa depois da denúncia"], "explicacao": "Art. 155, § 2º, do CP."}, {"id": 10081, "materia": "pen", "nivel": 1, "enunciado": "Obrigar alguém, com grave ameaça, a fazer uma transferência bancária para obter vantagem é:", "opcoes": ["Extorsão", "Roubo", "Estelionato", "Constrangimento ilegal"], "explicacao": "Art. 158 do CP: a vítima é forçada a fazer algo para o agente obter vantagem."}, {"id": 10082, "materia": "pen", "nivel": 1, "enunciado": "O “sequestro-relâmpago”, em que a vítima tem a liberdade restringida para o agente obter vantagem econômica, é tipificado como:", "opcoes": ["Extorsão com restrição da liberdade da vítima", "Sequestro e cárcere privado, com fim de lucro", "Roubo simples", "Extorsão mediante sequestro"], "explicacao": "Art. 158, § 3º, do CP."}, {"id": 10083, "materia": "pen", "nivel": 1, "enunciado": "Pelo Código Penal, o crime está consumado quando:", "opcoes": ["Reúne todos os elementos da definição legal", "O agente inicia a execução", "O agente termina de planejar e preparar o crime", "A vítima registra a ocorrência"], "explicacao": "Art. 14, I, do CP."}, {"id": 10084, "materia": "pen", "nivel": 1, "enunciado": "Em regra, a pena da tentativa é:", "opcoes": ["A do consumado, diminuída de 1/3 a 2/3", "Igual à do crime consumado", "A do crime consumado, reduzida pela metade", "Somente a pena de multa"], "explicacao": "Art. 14, parágrafo único, do CP."}, {"id": 10085, "materia": "pen", "nivel": 1, "enunciado": "No arrependimento posterior, nos crimes sem violência ou grave ameaça, o dano deve ser reparado até:", "opcoes": ["O recebimento da denúncia ou da queixa", "A sentença de primeiro grau", "O trânsito em julgado", "O relatório final do inquérito policial"], "explicacao": "Art. 16 do CP: a pena é reduzida de um a dois terços."}, {"id": 10086, "materia": "pen", "nivel": 1, "enunciado": "É excludente de ilicitude prevista no art. 23 do Código Penal:", "opcoes": ["O estrito cumprimento de dever legal", "A coação moral irresistível", "A embriaguez completa por caso fortuito", "O erro de proibição inevitável"], "explicacao": "As demais opções afastam a culpabilidade, não a ilicitude."}, {"id": 10087, "materia": "pen", "nivel": 1, "enunciado": "A legítima defesa exige reação moderada a uma agressão:", "opcoes": ["Injusta, atual ou iminente", "Justa, ainda que já encerrada", "Qualquer, mesmo já passada", "Apenas contra a própria vida"], "explicacao": "Art. 25 do CP."}, {"id": 10088, "materia": "pen", "nivel": 1, "enunciado": "Pelo Código Penal, a emoção e a paixão:", "opcoes": ["Não excluem a imputabilidade penal", "Excluem a imputabilidade penal", "Reduzem sempre a pena pela metade, em qualquer caso", "Tornam o crime sempre culposo"], "explicacao": "Art. 28, I, do CP."}, {"id": 10089, "materia": "pen", "nivel": 1, "enunciado": "Um caixa de loja fica com parte do dinheiro que recebe dos clientes e que deveria repassar ao patrão. Ele comete:", "opcoes": ["Apropriação indébita", "Furto simples", "Estelionato", "Peculato"], "explicacao": "Tinha a posse lícita do dinheiro e passou a agir como dono: art. 168 do CP."}, {"id": 10090, "materia": "pen", "nivel": 1, "enunciado": "Dois homens entram juntos numa casa vazia e levam a TV. Pelo concurso de duas pessoas, o furto é:", "opcoes": ["Qualificado", "Privilegiado", "Simples", "Majorado pelo repouso"], "explicacao": "Art. 155, § 4º, IV, do CP."}, {"id": 10091, "materia": "pen", "nivel": 1, "enunciado": "Ana pega o celular da colega sem violência e o devolve no dia seguinte, ao ser descoberta. O crime de furto:", "opcoes": ["Já estava consumado", "Ficou só na tentativa", "Não existiu", "Virou apropriação indébita"], "explicacao": "O furto se consuma com a posse do bem; a devolução pode influir na pena, não na consumação."}, {"id": 10092, "materia": "pen", "nivel": 1, "enunciado": "Mário liga para uma idosa fingindo ser do banco e a convence a transferir dinheiro para a conta dele. Pela Lei 14.155/2021, isso pode configurar:", "opcoes": ["Estelionato, com pena aumentada por ser a vítima idosa", "Furto qualificado pelo abuso de confiança e pela fraude", "Roubo, pela grave ameaça psicológica", "Apropriação indébita do cartão"], "explicacao": "Art. 171, § 4º, do CP."}, {"id": 10093, "materia": "pen", "nivel": 1, "enunciado": "Para o STF, o princípio da insignificância exclui:", "opcoes": ["A tipicidade material do fato", "A culpabilidade do agente", "A ilicitude do fato", "A punibilidade, após a sentença"], "explicacao": "Exige mínima ofensividade, nenhuma periculosidade social, reduzido grau de reprovabilidade e lesão inexpressiva."}, {"id": 10094, "materia": "pen", "nivel": 1, "enunciado": "Quem deixa de pagar, sem justa causa, a pensão alimentícia fixada para o filho pode responder por:", "opcoes": ["Abandono material", "Abandono de incapaz", "Apropriação indébita", "Estelionato"], "explicacao": "Art. 244 do CP."}, {"id": 10095, "materia": "port", "nivel": 1, "enunciado": "Assinale a frase com concordância correta:", "opcoes": ["Faz dois anos que ele saiu.", "Fazem dois anos que ele saiu.", "Houveram muitos problemas.", "Haviam muitas pessoas na sala."], "explicacao": "“Fazer” indicando tempo e “haver” no sentido de existir são impessoais."}, {"id": 10096, "materia": "port", "nivel": 1, "enunciado": "Em “Houve muitas prisões”, o verbo “haver” é:", "opcoes": ["Impessoal, por indicar existência", "Pessoal, concordando com “prisões”", "Auxiliar de um tempo composto", "De ligação, como o verbo ser"], "explicacao": "No sentido de existir, “haver” fica no singular."}, {"id": 10097, "materia": "port", "nivel": 1, "enunciado": "Assinale a forma correta:", "opcoes": ["Por que você faltou?", "Porque você faltou?", "Por quê você faltou?", "Porquê você faltou?"], "explicacao": "Em perguntas diretas, no início, usa-se “por que” separado e sem acento."}, {"id": 10098, "materia": "port", "nivel": 1, "enunciado": "Em “O delegado, que é experiente, conduziu o caso”, a oração “que é experiente” é:", "opcoes": ["Adjetiva explicativa", "Adjetiva restritiva", "Substantiva subjetiva", "Adverbial causal"], "explicacao": "Vem entre vírgulas e acrescenta uma informação."}, {"id": 10099, "materia": "port", "nivel": 1, "enunciado": "Em “Os documentos que estavam na mesa sumiram”, a oração “que estavam na mesa” é:", "opcoes": ["Adjetiva restritiva", "Adjetiva explicativa", "Adverbial temporal", "Substantiva objetiva"], "explicacao": "Restringe: só os documentos que estavam na mesa."}, {"id": 10100, "materia": "port", "nivel": 1, "enunciado": "No sentido de “ver”, o uso correto do verbo “assistir” é:", "opcoes": ["Assisti ao julgamento.", "Assisti o julgamento.", "Assisti no julgamento.", "Assisti pelo julgamento."], "explicacao": "No sentido de ver, “assistir” pede a preposição “a”."}, {"id": 10101, "materia": "port", "nivel": 1, "enunciado": "Assinale a frase correta quanto à regência do verbo “preferir”:", "opcoes": ["Prefiro investigar a esperar.", "Prefiro mais investigar do que esperar.", "Prefiro investigar do que esperar.", "Prefiro mais investigar que esperar."], "explicacao": "Prefere-se uma coisa a outra, sem “mais” e sem “do que”."}, {"id": 10102, "materia": "port", "nivel": 1, "enunciado": "Pelo Acordo Ortográfico, está correta a grafia:", "opcoes": ["Micro-ondas", "Microondas", "Auto-escola", "Semi-novo"], "explicacao": "Hífen quando o prefixo termina na mesma vogal que inicia a palavra seguinte."}, {"id": 10103, "materia": "ppen", "nivel": 1, "enunciado": "Nos crimes de ação pública condicionada, a representação é irretratável depois de:", "opcoes": ["Oferecida a denúncia", "Instaurado o inquérito", "Recebida a denúncia", "Proferida a sentença"], "explicacao": "Art. 25 do CPP."}, {"id": 10104, "materia": "ppen", "nivel": 1, "enunciado": "Em regra, o prazo para oferecer queixa ou representação é de:", "opcoes": ["6 meses, desde que se sabe quem é o autor", "30 dias, a partir da data do fato criminoso", "1 ano, a partir da data do fato", "6 meses, a partir da data do fato"], "explicacao": "Art. 38 do CPP: prazo decadencial."}, {"id": 10105, "materia": "ppen", "nivel": 1, "enunciado": "Com o réu preso, o Ministério Público deve oferecer a denúncia em:", "opcoes": ["5 dias", "15 dias", "10 dias", "30 dias"], "explicacao": "Art. 46 do CPP."}, {"id": 10106, "materia": "ppen", "nivel": 1, "enunciado": "Nos crimes comuns, a prisão temporária dura:", "opcoes": ["5 dias, prorrogáveis por mais 5", "10 dias, prorrogáveis por mais 10", "30 dias, prorrogáveis por mais 30", "15 dias, sem prorrogação"], "explicacao": "Art. 2º da Lei 7.960/1989."}, {"id": 10107, "materia": "ppen", "nivel": 1, "enunciado": "A prisão temporária só pode ser decretada:", "opcoes": ["Durante o inquérito policial", "Em qualquer fase do processo", "Depois da sentença condenatória", "Pelo próprio delegado de polícia"], "explicacao": "Lei 7.960/1989: é imprescindível para as investigações."}, {"id": 10108, "materia": "ppen", "nivel": 1, "enunciado": "No reconhecimento de pessoas, o CPP manda começar:", "opcoes": ["Pedindo à pessoa que descreva quem será reconhecido", "Mostrando ao reconhecedor uma única foto do suspeito", "Deixando o suspeito sozinho em uma sala", "Ouvindo a voz do suspeito por telefone"], "explicacao": "Art. 226, I, do CPP."}, {"id": 10109, "materia": "ppen", "nivel": 1, "enunciado": "A acareação é admitida entre pessoas:", "opcoes": ["Cujas declarações divergem sobre fatos relevantes", "Que ainda não foram ouvidas no processo", "Indicadas apenas pelo advogado de defesa do réu preso", "Que sejam peritos oficiais do caso"], "explicacao": "Art. 229 do CPP."}, {"id": 10110, "materia": "ppen", "nivel": 1, "enunciado": "O juiz das garantias é responsável pelo:", "opcoes": ["Controle da legalidade da investigação", "Julgamento do mérito da ação penal", "Acompanhamento da execução da pena", "Julgamento dos crimes dolosos contra a vida"], "explicacao": "Art. 3º-B do CPP."}, {"id": 10111, "materia": "ppen", "nivel": 1, "enunciado": "O acordo de não persecução penal cabe, sem violência ou grave ameaça, se a pena mínima do crime for inferior a:", "opcoes": ["4 anos", "2 anos", "8 anos", "1 ano"], "explicacao": "Art. 28-A do CPP."}, {"id": 10112, "materia": "ppen", "nivel": 1, "enunciado": "Quem propõe o acordo de não persecução penal é o:", "opcoes": ["Ministério Público", "Delegado de polícia", "Juiz da causa", "Defensor público"], "explicacao": "Art. 28-A do CPP."}, {"id": 10113, "materia": "ppen", "nivel": 1, "enunciado": "Arquivado o inquérito, a autoridade policial pode fazer novas pesquisas se:", "opcoes": ["Tiver notícia de outras provas", "O investigado concordar por escrito", "Passarem 5 anos", "O juiz for substituído"], "explicacao": "Art. 18 do CPP e Súmula 524 do STF."}, {"id": 10114, "materia": "ppen", "nivel": 1, "enunciado": "No auto de prisão em flagrante, ouve-se primeiro:", "opcoes": ["O condutor", "O preso", "A vítima", "O advogado"], "explicacao": "Art. 304 do CPP: condutor, testemunhas e, por fim, o preso."}, {"id": 10115, "materia": "ppen", "nivel": 1, "enunciado": "Na audiência de custódia, o juiz pode, entre outras decisões:", "opcoes": ["Relaxar a prisão ilegal", "Condenar o preso pelo crime", "Aplicar a pena final", "Arquivar a ação penal"], "explicacao": "Art. 310 do CPP: relaxar, converter em preventiva ou conceder liberdade provisória."}, {"id": 10116, "materia": "ppen", "nivel": 1, "enunciado": "A vítima de um crime de ação pública condicionada quer que o caso seja investigado. Ela deve apresentar:", "opcoes": ["Representação", "Queixa-crime", "Denúncia", "Habeas corpus"], "explicacao": "Art. 5º, § 4º, do CPP."}, {"id": 10117, "materia": "ppen", "nivel": 1, "enunciado": "O policial que conduz o preso até o delegado, no flagrante, é chamado de:", "opcoes": ["Condutor", "Escrivão", "Custodiante", "Perito"], "explicacao": "Art. 304 do CPP."}, {"id": 10118, "materia": "rl", "nivel": 1, "enunciado": "A negação de “Todos os presos fugiram” é:", "opcoes": ["Algum preso não fugiu", "Nenhum preso fugiu", "Todos os presos ficaram", "Algum preso fugiu"], "explicacao": "Para negar o “todos”, basta um contraexemplo."}, {"id": 10119, "materia": "rl", "nivel": 1, "enunciado": "A negação de “Algum agente faltou” é:", "opcoes": ["Nenhum agente faltou", "Todos os agentes faltaram", "Algum agente não faltou", "Nem todos os agentes faltaram"], "explicacao": "A negação de “algum” é “nenhum”."}, {"id": 10120, "materia": "rl", "nivel": 1, "enunciado": "A proposição “Se chove, então a rua molha” é falsa quando:", "opcoes": ["Chove e a rua não molha", "Não chove e a rua molha", "Não chove e a rua não molha", "Chove e a rua molha"], "explicacao": "A condicional só é falsa com antecedente verdadeiro e consequente falso."}, {"id": 10121, "materia": "rl", "nivel": 1, "enunciado": "Numa sala com 30 pessoas, 18 são homens. A porcentagem de mulheres é:", "opcoes": ["40%", "60%", "30%", "45%"], "explicacao": "12 mulheres de 30: 12/30 = 40%."}, {"id": 10122, "materia": "rl", "nivel": 1, "enunciado": "A negação de “Pedro é escrivão ou Ana é perita” é:", "opcoes": ["Pedro não é escrivão e Ana não é perita", "Pedro não é escrivão ou Ana não é perita", "Pedro é escrivão e Ana é perita", "Se Pedro é escrivão, Ana não é perita"], "explicacao": "¬(P ∨ Q) = ¬P ∧ ¬Q."}, {"id": 10123, "materia": "rl", "nivel": 1, "enunciado": "Uma operação reuniu 40 policiais, dos quais 15% eram mulheres. Quantas mulheres participaram?", "opcoes": ["6", "4", "8", "15"], "explicacao": "15% de 40 = 6."}, {"id": 10124, "materia": "rl", "nivel": 1, "enunciado": "Um carro gasta 8 litros a cada 100 km. Para 350 km, gasta:", "opcoes": ["28 litros", "24 litros", "32 litros", "35 litros"], "explicacao": "3,5 × 8 = 28."}, {"id": 10125, "materia": "adm", "nivel": 2, "enunciado": "Nomear cônjuge ou parente até o terceiro grau da autoridade para cargo em comissão viola a:", "opcoes": ["Súmula Vinculante 13 do STF", "Súmula 473 do STF", "Súmula Vinculante 11 do STF", "Súmula 7 do STJ"], "explicacao": "Vedação ao nepotismo."}, {"id": 10126, "materia": "adm", "nivel": 2, "enunciado": "O Estado responde objetivamente pelos danos, com direito de regresso contra o agente que agiu com:", "opcoes": ["Dolo ou culpa", "Boa-fé", "Ordem superior", "Autorização legal"], "explicacao": "Art. 37, § 6º, da CF."}, {"id": 10127, "materia": "adm", "nivel": 2, "enunciado": "Desde a Lei 14.230/2021, os atos de improbidade administrativa exigem:", "opcoes": ["Dolo", "Culpa grave", "Culpa leve", "Simples erro"], "explicacao": "Art. 1º, § 1º, da Lei 8.429/1992."}, {"id": 10128, "materia": "adm", "nivel": 2, "enunciado": "Entre as sanções por improbidade administrativa estão:", "opcoes": ["Perda da função, suspensão dos direitos políticos e multa", "Prisão em regime fechado e perda da nacionalidade", "Pena de reclusão e cassação do diploma universitário", "Apenas advertência por escrito e transferência obrigatória de setor"], "explicacao": "Art. 12 da Lei 8.429/1992."}, {"id": 10129, "materia": "adm", "nivel": 2, "enunciado": "Na Lei 8.112/1990, a advertência é aplicada por escrito quando:", "opcoes": ["Há falta a dever funcional sem gravidade maior", "Há abandono de cargo por mais de 30 dias", "Há crime contra a administração pública e dano ao erário", "Há recebimento de propina"], "explicacao": "Art. 129 da Lei 8.112/1990."}, {"id": 10130, "materia": "adm", "nivel": 2, "enunciado": "Na Lei 8.112/1990, abandono de cargo é a ausência intencional ao serviço por mais de:", "opcoes": ["30 dias seguidos", "15 dias seguidos", "60 dias alternados", "10 dias seguidos"], "explicacao": "Art. 138 da Lei 8.112/1990."}, {"id": 10131, "materia": "adm", "nivel": 2, "enunciado": "A inassiduidade habitual é a falta ao serviço, sem causa justificada, por:", "opcoes": ["60 dias, alternados, em 12 meses", "30 dias seguidos, dentro de um período de 12 meses", "90 dias, alternados, no ano", "15 dias seguidos, no mês"], "explicacao": "Art. 139 da Lei 8.112/1990."}, {"id": 10132, "materia": "adm", "nivel": 2, "enunciado": "O prazo para concluir o PAD é de:", "opcoes": ["60 dias, prorrogável por igual prazo", "30 dias, sem prorrogação", "120 dias, sem possibilidade de prorrogação", "90 dias, prorrogável uma única vez"], "explicacao": "Art. 152 da Lei 8.112/1990."}, {"id": 10133, "materia": "adm", "nivel": 2, "enunciado": "Na Lei 8.112/1990, a cassação de aposentadoria é aplicada ao inativo que praticou, na atividade, falta punível com:", "opcoes": ["Demissão", "Advertência", "Suspensão", "Multa"], "explicacao": "Art. 134 da Lei 8.112/1990."}, {"id": 10134, "materia": "adm", "nivel": 2, "enunciado": "Um servidor que usa o carro oficial para fins particulares fere principalmente o princípio da:", "opcoes": ["Moralidade", "Publicidade", "Eficiência", "Hierarquia"], "explicacao": "Uso de bem público para interesse privado."}, {"id": 10135, "materia": "adm", "nivel": 2, "enunciado": "O ato administrativo que concede porte de arma a quem cumpre os requisitos, sem dever de concedê-lo, é exemplo de ato:", "opcoes": ["Discricionário", "Vinculado", "Normativo", "Enunciativo"], "explicacao": "A autorização de porte é ato discricionário e precário."}, {"id": 10136, "materia": "const", "nivel": 2, "enunciado": "O Presidente da República é eleito para mandato de:", "opcoes": ["4 anos, permitida uma reeleição", "5 anos, sem reeleição", "4 anos, sem reeleição", "6 anos, permitida uma reeleição"], "explicacao": "Arts. 14, § 5º, e 82 da CF."}, {"id": 10137, "materia": "const", "nivel": 2, "enunciado": "O alistamento e o voto são facultativos para:", "opcoes": ["Analfabetos, maiores de 70 e jovens de 16 e 17 anos", "Todos os maiores de 18 anos", "Servidores públicos e militares", "Brasileiros que moram no exterior há mais de um ano"], "explicacao": "Art. 14, § 1º, II, da CF."}, {"id": 10138, "materia": "const", "nivel": 2, "enunciado": "Não podem alistar-se como eleitores:", "opcoes": ["Os estrangeiros e os conscritos no serviço militar", "Os analfabetos e os maiores de 70 anos de idade", "Os jovens de 16 e 17 anos", "Os servidores públicos ainda em estágio probatório"], "explicacao": "Art. 14, § 2º, da CF."}, {"id": 10139, "materia": "const", "nivel": 2, "enunciado": "O Presidente da República, nos crimes comuns, é julgado pelo:", "opcoes": ["Supremo Tribunal Federal", "Senado Federal", "Superior Tribunal de Justiça", "Congresso Nacional"], "explicacao": "Art. 102, I, b, da CF."}, {"id": 10140, "materia": "const", "nivel": 2, "enunciado": "Nos crimes de responsabilidade, o Presidente da República é julgado pelo:", "opcoes": ["Senado Federal", "Supremo Tribunal Federal", "Superior Tribunal de Justiça", "Câmara dos Deputados"], "explicacao": "Art. 86 da CF. A Câmara autoriza a acusação."}, {"id": 10141, "materia": "const", "nivel": 2, "enunciado": "Os governadores, nos crimes comuns, são julgados pelo:", "opcoes": ["Superior Tribunal de Justiça", "Supremo Tribunal Federal", "Tribunal de Justiça do estado", "Assembleia Legislativa"], "explicacao": "Art. 105, I, a, da CF."}, {"id": 10142, "materia": "const", "nivel": 2, "enunciado": "Os prefeitos são julgados perante o:", "opcoes": ["Tribunal de Justiça", "Superior Tribunal de Justiça", "Juiz de primeiro grau", "Câmara Municipal"], "explicacao": "Art. 29, X, da CF."}, {"id": 10143, "materia": "const", "nivel": 2, "enunciado": "Entre as funções da Polícia Federal está:", "opcoes": ["Ser a polícia judiciária da União, com exclusividade", "Fazer o policiamento ostensivo nas cidades do interior", "Guardar os presídios estaduais", "Patrulhar as rodovias federais"], "explicacao": "Art. 144, § 1º, IV, da CF."}, {"id": 10144, "materia": "const", "nivel": 2, "enunciado": "As Forças Armadas são instituições:", "opcoes": ["Nacionais, permanentes e regulares", "Estaduais e temporárias", "Municipais, permanentes e regulares", "Privadas e regulares"], "explicacao": "Art. 142 da CF."}, {"id": 10145, "materia": "const", "nivel": 2, "enunciado": "A Força Nacional de Segurança Pública é formada, em regra, por:", "opcoes": ["Policiais e bombeiros dos estados, em cooperação", "Militares do Exército, apenas, por convocação federal", "Guardas municipais concursados", "Agentes contratados sem concurso"], "explicacao": "Lei 11.473/2007 e Decreto 5.289/2004."}, {"id": 10146, "materia": "const", "nivel": 2, "enunciado": "Pela Constituição, a lei só poderá restringir a publicidade dos atos processuais quando a defesa da intimidade ou o interesse social o exigirem. Isso é exceção ao princípio da:", "opcoes": ["Publicidade", "Legalidade", "Eficiência", "Moralidade"], "explicacao": "Art. 5º, LX, da CF."}, {"id": 10147, "materia": "dh", "nivel": 2, "enunciado": "As Regras de Bangkok, da ONU, tratam do tratamento de:", "opcoes": ["Mulheres presas", "Crianças em abrigos", "Presos estrangeiros", "Idosos internados"], "explicacao": "Também tratam de medidas não privativas de liberdade para mulheres."}, {"id": 10148, "materia": "dh", "nivel": 2, "enunciado": "O caso Maria da Penha foi analisado pela:", "opcoes": ["Comissão Interamericana de Direitos Humanos", "Corte Internacional de Justiça", "Corte Interamericana, em sentença", "Assembleia Geral da ONU, em resolução especial"], "explicacao": "Relatório de 2001, que responsabilizou o Brasil."}, {"id": 10149, "materia": "dh", "nivel": 2, "enunciado": "A primeira condenação do Brasil na Corte Interamericana foi no caso:", "opcoes": ["Damião Ximenes Lopes", "Herzog", "Gomes Lund", "Favela Nova Brasília"], "explicacao": "Sentença de 2006, sobre morte em clínica psiquiátrica."}, {"id": 10150, "materia": "dh", "nivel": 2, "enunciado": "O caso Favela Nova Brasília (2017) tratou de:", "opcoes": ["Mortes e violência sexual em operações policiais", "Trabalho escravo em fazenda no sul do Pará, nos anos 1990", "Desaparecimentos na Guerrilha do Araguaia", "Morte de paciente em clínica no Ceará"], "explicacao": "Corte Interamericana de Direitos Humanos."}, {"id": 10151, "materia": "dh", "nivel": 2, "enunciado": "O caso Gomes Lund (Guerrilha do Araguaia) tratou de:", "opcoes": ["Desaparecimentos forçados na ditadura", "Violência policial em favela do Rio de Janeiro", "Trabalho escravo", "Morte de jornalista"], "explicacao": "Sentença de 2010."}, {"id": 10152, "materia": "dh", "nivel": 2, "enunciado": "O Protocolo Facultativo à Convenção contra a Tortura prevê:", "opcoes": ["Visitas a locais de privação de liberdade", "Pena de morte para torturadores condenados", "Extradição automática de agentes", "Anistia aos agentes do Estado"], "explicacao": "Mecanismos nacionais e o Subcomitê de Prevenção."}, {"id": 10153, "materia": "igual", "nivel": 2, "enunciado": "Os crimes da Lei 7.716/1989 são:", "opcoes": ["Inafiançáveis e imprescritíveis", "Afiançáveis, mas imprescritíveis", "De ação penal privada", "De menor potencial ofensivo"], "explicacao": "Art. 5º, XLII, da CF."}, {"id": 10154, "materia": "igual", "nivel": 2, "enunciado": "Em 2019, o STF enquadrou a homotransfobia no crime de:", "opcoes": ["Racismo", "Injúria simples", "Ameaça", "Constrangimento ilegal"], "explicacao": "ADO 26 e MI 4733."}, {"id": 10155, "materia": "igual", "nivel": 2, "enunciado": "Pela Lei 14.532/2023, o racismo praticado em atividade esportiva ou artística pode levar, além da prisão, à:", "opcoes": ["Proibição de frequentar locais de esporte, arte ou cultura", "Perda da nacionalidade brasileira, se o autor for naturalizado", "Cassação da carteira de motorista", "Prisão perpétua"], "explicacao": "Art. 20, § 2º-A, da Lei 7.716/1989."}, {"id": 10156, "materia": "igual", "nivel": 2, "enunciado": "A injúria racial cometida por funcionário público no exercício da função, pela Lei 14.532/2023, tem a pena:", "opcoes": ["Aumentada de 1/3 até a metade", "Reduzida de um terço", "Igual à da injúria comum", "Convertida em multa e serviços"], "explicacao": "Art. 20-B da Lei 7.716/1989."}, {"id": 10157, "materia": "inf", "nivel": 2, "enunciado": "O worm se diferencia do vírus porque:", "opcoes": ["Se propaga sozinho pela rede, sem hospedeiro", "Funciona só em celulares", "Não causa nenhum tipo de dano", "Precisa sempre ser aberto e executado pelo usuário"], "explicacao": "O vírus precisa de um arquivo hospedeiro e da execução."}, {"id": 10158, "materia": "inf", "nivel": 2, "enunciado": "O spyware é um programa que:", "opcoes": ["Coleta dados do usuário sem ele saber", "Sequestra os arquivos e pede um resgate", "Abre uma porta para o invasor voltar", "Mostra anúncios, sem coletar dados"], "explicacao": "Ransomware sequestra; backdoor abre portas."}, {"id": 10159, "materia": "inf", "nivel": 2, "enunciado": "O keylogger registra:", "opcoes": ["As teclas digitadas", "As imagens da webcam", "Os arquivos excluídos", "A velocidade da rede"], "explicacao": "É um tipo de spyware."}, {"id": 10160, "materia": "inf", "nivel": 2, "enunciado": "No Excel, =MÉDIA(2;4;6) resulta em:", "opcoes": ["4", "12", "6", "3"], "explicacao": "(2 + 4 + 6) / 3 = 4."}, {"id": 10161, "materia": "inf", "nivel": 2, "enunciado": "O backup incremental copia:", "opcoes": ["Só o que mudou desde o último backup feito", "Todos os arquivos, sempre", "Só o que mudou desde o último backup completo", "Apenas os arquivos do sistema"], "explicacao": "O diferencial copia o que mudou desde o último completo."}, {"id": 10162, "materia": "inf", "nivel": 2, "enunciado": "O ransomware costuma:", "opcoes": ["Criptografar os arquivos e cobrar resgate", "Mostrar propagandas na tela sem parar, sem roubar dados", "Registrar o que se digita", "Abrir uma porta para o invasor"], "explicacao": "Pede pagamento, muitas vezes em criptomoeda."}, {"id": 10163, "materia": "inf", "nivel": 2, "enunciado": "O cavalo de troia (trojan) é um programa que:", "opcoes": ["Parece legítimo, mas age de forma maliciosa", "Se replica sozinho pela rede, sem o usuário", "Criptografa arquivos e pede resgate", "Apenas exibe anúncios no navegador"], "explicacao": "Entra disfarçado de programa útil."}, {"id": 10164, "materia": "leg", "nivel": 2, "enunciado": "Para o servidor público, a condenação por tortura acarreta:", "opcoes": ["A perda do cargo e a proibição de exercê-lo pelo dobro da pena", "Apenas a suspensão do cargo por 30 dias", "Advertência por escrito no assentamento funcional do servidor", "Transferência obrigatória para outro setor, sem perda do cargo"], "explicacao": "Art. 1º, § 5º, da Lei 9.455/1997."}, {"id": 10165, "materia": "leg", "nivel": 2, "enunciado": "Na forma básica, a tortura tem pena de:", "opcoes": ["Reclusão de 2 a 8 anos", "Reclusão de 4 a 10 anos", "Detenção de 1 a 4 anos", "Reclusão de 8 a 16 anos"], "explicacao": "Art. 1º da Lei 9.455/1997."}, {"id": 10166, "materia": "leg", "nivel": 2, "enunciado": "A Lei de Tortura se aplica a crime cometido fora do Brasil quando a vítima é brasileira ou quando:", "opcoes": ["O agente está sob jurisdição brasileira", "O agente é estrangeiro e está fora do Brasil", "Há tratado bilateral de extradição", "O crime é culposo"], "explicacao": "Art. 2º da Lei 9.455/1997."}, {"id": 10167, "materia": "leg", "nivel": 2, "enunciado": "Pela Lei 13.869/2019, a divergência na interpretação da lei ou na avaliação de provas:", "opcoes": ["Não configura, por si só, abuso", "Configura crime de abuso de autoridade", "Configura falta disciplinar grave", "Gera a perda automática do cargo"], "explicacao": "Art. 1º, § 2º, da Lei 13.869/2019."}, {"id": 10168, "materia": "leg", "nivel": 2, "enunciado": "Constranger o preso, com violência, a exibir-se à curiosidade pública é:", "opcoes": ["Crime de abuso de autoridade", "Apenas infração disciplinar leve", "Fato atípico", "Contravenção penal"], "explicacao": "Art. 13, I, da Lei 13.869/2019."}, {"id": 10169, "materia": "leg", "nivel": 2, "enunciado": "Pelo Estatuto do Desarmamento, disparar arma de fogo em lugar habitado tem pena de:", "opcoes": ["Reclusão de 2 a 4 anos e multa", "Detenção de 1 a 3 anos e multa", "Reclusão de 4 a 8 anos e multa", "Detenção de 6 meses a 1 ano"], "explicacao": "Art. 15 da Lei 10.826/2003."}, {"id": 10170, "materia": "leg", "nivel": 2, "enunciado": "A posse ou o porte ilegal de arma de fogo de uso proibido é crime:", "opcoes": ["Hediondo", "De menor potencial ofensivo", "Culposo", "Afiançável pelo delegado"], "explicacao": "Art. 1º, parágrafo único, II, da Lei 8.072/1990."}, {"id": 10171, "materia": "leg", "nivel": 2, "enunciado": "Pelo CTB, entregar a direção do veículo a pessoa não habilitada é:", "opcoes": ["Crime", "Fato atípico", "Só infração leve", "Contravenção"], "explicacao": "Art. 310 do CTB."}, {"id": 10172, "materia": "leg", "nivel": 2, "enunciado": "Na Lei de Drogas, a pena do tráfico aumenta se for praticado nas imediações de:", "opcoes": ["Escolas, hospitais e unidades militares ou policiais", "Shopping centers, estádios de futebol e casas de show", "Rodoviárias e aeroportos privados", "Qualquer lugar com mais de 100 pessoas"], "explicacao": "Art. 40, III, da Lei 11.343/2006."}, {"id": 10173, "materia": "leg", "nivel": 2, "enunciado": "Na Lei de Drogas, o tráfico entre estados da Federação:", "opcoes": ["Aumenta a pena de 1/6 a 2/3", "É julgado pela Justiça Federal", "Não altera a pena", "Dobra a pena"], "explicacao": "Art. 40, V, da Lei 11.343/2006. A competência continua estadual."}, {"id": 10174, "materia": "leg", "nivel": 2, "enunciado": "Na Lei de Drogas, o laudo de constatação, para lavrar o flagrante e oferecer a denúncia, é:", "opcoes": ["Suficiente para a materialidade nessa fase", "Dispensável em qualquer caso, se houver confissão", "Igual ao laudo definitivo", "Feito só pelo juiz"], "explicacao": "Art. 50, § 1º, da Lei 11.343/2006."}, {"id": 10175, "materia": "leg", "nivel": 2, "enunciado": "Pelo Estatuto do Desarmamento, raspar a numeração de uma arma de fogo é crime equiparado ao:", "opcoes": ["Porte ou posse de arma de uso restrito", "Disparo de arma de fogo", "Comércio ilegal de armas", "Tráfico internacional de arma de fogo, sempre"], "explicacao": "Art. 16, § 1º, IV, da Lei 10.826/2003."}, {"id": 10176, "materia": "leg", "nivel": 2, "enunciado": "Pelo ECA, o ato infracional é a conduta:", "opcoes": ["Descrita como crime ou contravenção", "Contrária às regras da escola ou do clube", "Desobediente aos pais", "Prevista só no Código Civil"], "explicacao": "Art. 103 do ECA."}, {"id": 10177, "materia": "leg", "nivel": 2, "enunciado": "Pelo ECA, à criança que pratica ato infracional aplicam-se:", "opcoes": ["Medidas de proteção", "Medidas socioeducativas", "Penas de prisão", "Multas aos pais, apenas"], "explicacao": "Art. 105 do ECA."}, {"id": 10178, "materia": "ml", "nivel": 2, "enunciado": "A zona de tatuagem, em ferida por arma de fogo, indica tiro:", "opcoes": ["A curta distância", "A longa distância", "Sempre encostado", "Com ricochete"], "explicacao": "Grãos de pólvora incrustados na pele."}, {"id": 10179, "materia": "ml", "nivel": 2, "enunciado": "A câmara de mina de Hoffmann é típica do tiro:", "opcoes": ["Encostado, sobre osso logo abaixo da pele", "A longa distância, sobre região muscular espessa", "A curta distância, sem encostar na pele", "Ricocheteado em superfície dura"], "explicacao": "Os gases descolam e rompem os tecidos."}, {"id": 10180, "materia": "ml", "nivel": 2, "enunciado": "A orla de escoriação (contusão) aparece no orifício de:", "opcoes": ["Entrada", "Saída", "Entrada e saída", "Nenhum dos dois"], "explicacao": "O projétil arranca a epiderme ao entrar."}, {"id": 10181, "materia": "ml", "nivel": 2, "enunciado": "A rigidez cadavérica costuma começar:", "opcoes": ["Pela mandíbula e pela nuca", "Pelos pés", "Pelas mãos", "Pelo abdome"], "explicacao": "Segue a lei de Nysten, de cima para baixo."}, {"id": 10182, "materia": "ml", "nivel": 2, "enunciado": "A mancha verde abdominal, primeiro sinal da putrefação, costuma surgir na:", "opcoes": ["Fossa ilíaca direita", "Região do tórax", "Face", "Planta dos pés"], "explicacao": "Perto do ceco, rico em bactérias."}, {"id": 10183, "materia": "ml", "nivel": 2, "enunciado": "No enforcamento, o sulco no pescoço costuma ser:", "opcoes": ["Oblíquo e interrompido no nó", "Horizontal e contínuo", "Inexistente", "Vertical"], "explicacao": "O peso do corpo puxa o laço para cima."}, {"id": 10184, "materia": "ml", "nivel": 2, "enunciado": "No estrangulamento por laço, o sulco costuma ser:", "opcoes": ["Horizontal e contínuo", "Oblíquo e interrompido", "Sempre inexistente", "Só na nuca"], "explicacao": "A força é externa e uniforme."}, {"id": 10185, "materia": "ml", "nivel": 2, "enunciado": "A orla de enxugo aparece no orifício de entrada porque o projétil:", "opcoes": ["Deixa na pele resíduos de sujeira e graxa", "Queima a pele com o calor intenso do disparo", "Arranca toda a pele ao redor", "Sai pelo outro lado com força"], "explicacao": "O projétil “limpa” suas impurezas na borda."}, {"id": 10186, "materia": "ml", "nivel": 2, "enunciado": "Na morte por queimadura em incêndio, a presença de fuligem nas vias aéreas indica que a vítima:", "opcoes": ["Respirava durante o incêndio", "Morreu antes de o fogo começar", "Foi envenenada", "Morreu afogada"], "explicacao": "Sinal de reação vital."}, {"id": 10187, "materia": "pcd", "nivel": 2, "enunciado": "Pela LBI, a curatela da pessoa com deficiência:", "opcoes": ["É extraordinária e atinge só atos patrimoniais e negociais", "Retira da pessoa todos os direitos civis e políticos, sem exceção", "É obrigatória em qualquer tipo de deficiência", "Impede a pessoa de votar e de se casar"], "explicacao": "Art. 85 da LBI."}, {"id": 10188, "materia": "pcd", "nivel": 2, "enunciado": "A tomada de decisão apoiada, prevista no Código Civil, é pedida:", "opcoes": ["Pela própria pessoa com deficiência", "Pelo Ministério Público, obrigatoriamente", "Pelo médico que acompanha a pessoa", "Pelo juiz, de ofício"], "explicacao": "Art. 1.783-A do Código Civil."}, {"id": 10189, "materia": "pcd", "nivel": 2, "enunciado": "Pela LBI, a pessoa com deficiência tem direito a votar e ser votada, inclusive com:", "opcoes": ["Ajuda de pessoa de sua escolha, se precisar", "Voto obrigatório em casa, com urna levada pelo mesário", "Dispensa do voto em qualquer caso", "Voto apenas por procuração"], "explicacao": "Art. 76 da LBI."}, {"id": 10190, "materia": "pen", "nivel": 2, "enunciado": "A lesão corporal que resulta perda ou inutilização de membro, sentido ou função é:", "opcoes": ["Gravíssima", "Grave", "Leve", "Privilegiada"], "explicacao": "Art. 129, § 2º, III, do CP."}, {"id": 10191, "materia": "pen", "nivel": 2, "enunciado": "O latrocínio (roubo seguido de morte) é julgado:", "opcoes": ["Pelo juiz singular, por ser crime patrimonial", "Pelo Tribunal do Júri, por envolver uma morte", "Pelo juiz da execução penal da comarca", "Pela Justiça Federal, por ser crime hediondo"], "explicacao": "Súmula 603 do STF."}, {"id": 10192, "materia": "pen", "nivel": 2, "enunciado": "O homicídio cometido por motivo fútil é:", "opcoes": ["Qualificado", "Privilegiado", "Culposo", "Simples"], "explicacao": "Art. 121, § 2º, II, do CP."}, {"id": 10193, "materia": "pen", "nivel": 2, "enunciado": "Com a Lei 14.994/2024, o feminicídio passou a ser:", "opcoes": ["Crime autônomo, com reclusão de 20 a 40 anos", "Qualificadora do homicídio, com 12 a 30 anos", "Causa de aumento do homicídio simples", "Crime de violência doméstica sem pena própria"], "explicacao": "Art. 121-A do CP."}, {"id": 10194, "materia": "pen", "nivel": 2, "enunciado": "No peculato culposo, se o servidor repara o dano antes da sentença irrecorrível:", "opcoes": ["Extingue-se a punibilidade", "A pena é reduzida pela metade", "Nada muda na pena", "A pena é aumentada de um terço"], "explicacao": "Art. 312, § 3º. Se reparar depois, a pena é reduzida pela metade."}, {"id": 10195, "materia": "pen", "nivel": 2, "enunciado": "A prevaricação consiste em:", "opcoes": ["Retardar ou deixar de praticar ato de ofício por interesse pessoal", "Exigir vantagem indevida em razão da função pública", "Solicitar ou receber vantagem indevida em razão da função pública", "Apropriar-se de bem público de que tem a posse em razão do cargo"], "explicacao": "Art. 319 do CP."}, {"id": 10196, "materia": "pen", "nivel": 2, "enunciado": "A denunciação caluniosa consiste em:", "opcoes": ["Provocar investigação contra quem sabe ser inocente", "Atribuir falsamente a alguém um fato criminoso numa conversa entre vizinhos", "Comunicar à polícia um crime que sabe que não ocorreu", "Acusar a si mesmo de crime praticado por outra pessoa"], "explicacao": "Art. 339 do CP. As outras opções são calúnia, comunicação falsa de crime e autoacusação falsa."}, {"id": 10197, "materia": "pen", "nivel": 2, "enunciado": "Fazer afirmação falsa como testemunha em inquérito policial é crime de:", "opcoes": ["Falso testemunho", "Falsidade ideológica", "Fraude processual", "Denunciação caluniosa"], "explicacao": "Art. 342 do CP."}, {"id": 10198, "materia": "pen", "nivel": 2, "enunciado": "Alterar artificiosamente o local do crime para enganar o juiz ou o perito é:", "opcoes": ["Fraude processual", "Falso testemunho", "Favorecimento real", "Coação no curso do processo"], "explicacao": "Art. 347 do CP."}, {"id": 10199, "materia": "pen", "nivel": 2, "enunciado": "Ajudar o autor de um crime a fugir da polícia, fora dos casos de coautoria, é:", "opcoes": ["Favorecimento pessoal", "Favorecimento real", "Receptação", "Fraude processual"], "explicacao": "Art. 348 do CP."}, {"id": 10200, "materia": "pen", "nivel": 2, "enunciado": "Ajudar o criminoso a tornar seguro o proveito do crime, fora dos casos de coautoria e receptação, é:", "opcoes": ["Favorecimento real", "Favorecimento pessoal", "Lavagem de dinheiro", "Receptação culposa"], "explicacao": "Art. 349 do CP."}, {"id": 10201, "materia": "pen", "nivel": 2, "enunciado": "Quanto ao tempo do crime, o Código Penal considera praticado o crime no momento:", "opcoes": ["Da ação ou da omissão", "Do resultado", "Da descoberta", "Da denúncia"], "explicacao": "Art. 4º do CP: teoria da atividade."}, {"id": 10202, "materia": "pen", "nivel": 2, "enunciado": "Paulo atira para matar Davi, que sobrevive após cirurgia. Paulo responde por:", "opcoes": ["Tentativa de homicídio", "Lesão corporal grave", "Lesão corporal seguida de morte", "Homicídio culposo"], "explicacao": "Iniciou a execução com dolo de matar, e a morte não ocorreu por circunstâncias alheias à sua vontade."}, {"id": 10203, "materia": "pen", "nivel": 2, "enunciado": "Ao fugir de um assalto, o ladrão empurra a vítima logo depois de pegar a bolsa, para garantir a fuga. Isso caracteriza:", "opcoes": ["Roubo impróprio", "Furto seguido de lesão", "Roubo próprio", "Extorsão"], "explicacao": "Art. 157, § 1º, do CP: violência logo depois da subtração para assegurar a impunidade ou a detenção da coisa."}, {"id": 10204, "materia": "pen", "nivel": 2, "enunciado": "O roubo com emprego de arma branca, após a Lei 13.964/2019, tem a pena aumentada de:", "opcoes": ["Um terço até metade", "Dois terços", "Um sexto a um terço", "O dobro"], "explicacao": "Art. 157, § 2º, VII, do CP."}, {"id": 10205, "materia": "pen", "nivel": 2, "enunciado": "Lúcio encontra um relógio perdido na praça e fica com ele, sem procurar o dono nem entregá-lo à autoridade em 15 dias. Ele comete:", "opcoes": ["Apropriação de coisa achada", "Furto simples", "Receptação", "Fato atípico, pois o dono perdeu"], "explicacao": "Art. 169, parágrafo único, II, do CP."}, {"id": 10206, "materia": "pen", "nivel": 2, "enunciado": "Tiago entra numa casa à noite, sem ninguém, rompe o cadeado do portão e leva uma bicicleta. Ele comete:", "opcoes": ["Furto qualificado pelo rompimento de obstáculo", "Furto qualificado, com aumento pelo repouso noturno", "Roubo, por ter entrado de noite na casa vazia", "Furto simples, com aumento pelo repouso noturno"], "explicacao": "Art. 155, § 4º, I, do CP. Pelo STJ (Tema 1.087), o aumento do repouso noturno não se aplica ao furto qualificado."}, {"id": 10207, "materia": "port", "nivel": 2, "enunciado": "Em “Aluga-se sala”, a partícula “se” é:", "opcoes": ["Pronome apassivador", "Índice de indeterminação do sujeito", "Pronome reflexivo", "Conjunção condicional"], "explicacao": "Voz passiva sintética: sala é alugada."}, {"id": 10208, "materia": "port", "nivel": 2, "enunciado": "Assinale a frase correta:", "opcoes": ["Alugam-se salas.", "Aluga-se salas.", "Precisam-se de agentes.", "Consertam-se o relógio."], "explicacao": "Na passiva sintética, o verbo concorda com o sujeito (salas)."}, {"id": 10209, "materia": "port", "nivel": 2, "enunciado": "Em “Precisa-se de policiais”, o “se” é:", "opcoes": ["Índice de indeterminação do sujeito", "Pronome apassivador", "Pronome reflexivo", "Parte integrante do verbo (pronominal)"], "explicacao": "O verbo pede preposição; o sujeito é indeterminado."}, {"id": 10210, "materia": "port", "nivel": 2, "enunciado": "A conjunção “embora” introduz ideia de:", "opcoes": ["Concessão", "Causa", "Conclusão", "Condição"], "explicacao": "Ex.: Embora cansado, terminou o plantão."}, {"id": 10211, "materia": "port", "nivel": 2, "enunciado": "A conjunção “portanto” indica:", "opcoes": ["Conclusão", "Oposição", "Causa", "Tempo"], "explicacao": "Ex.: Estudou; portanto, foi aprovado."}, {"id": 10212, "materia": "port", "nivel": 2, "enunciado": "Em “Caso chova, a operação será adiada”, “caso” indica:", "opcoes": ["Condição", "Concessão", "Causa", "Finalidade"], "explicacao": "Equivale a “se chover”."}, {"id": 10213, "materia": "port", "nivel": 2, "enunciado": "Assinale a colocação pronominal correta pela norma-padrão:", "opcoes": ["Não me disseram nada.", "Não disseram-me nada.", "Nunca viram-me lá.", "Quem contou-lhe o fato?"], "explicacao": "Palavras negativas e pronomes interrogativos atraem o pronome (próclise)."}, {"id": 10214, "materia": "port", "nivel": 2, "enunciado": "Em “Entregou o relatório ao delegado”, o termo “ao delegado” é:", "opcoes": ["Objeto indireto", "Objeto direto", "Adjunto adverbial", "Complemento nominal"], "explicacao": "Complementa o verbo com preposição: entregar a alguém."}, {"id": 10215, "materia": "ppen", "nivel": 2, "enunciado": "Decretada a prisão preventiva, a necessidade de mantê-la deve ser revista a cada:", "opcoes": ["90 dias", "30 dias", "180 dias", "60 dias"], "explicacao": "Art. 316, parágrafo único, do CPP."}, {"id": 10216, "materia": "ppen", "nivel": 2, "enunciado": "É medida cautelar diversa da prisão, prevista no CPP:", "opcoes": ["A monitoração eletrônica", "A prisão temporária", "A prisão em flagrante", "A condução coercitiva para interrogatório"], "explicacao": "Art. 319, IX, do CPP."}, {"id": 10217, "materia": "ppen", "nivel": 2, "enunciado": "A prisão preventiva pode ser substituída pela domiciliar, entre outros casos, se o agente for:", "opcoes": ["Maior de 80 anos", "Maior de 60 anos", "Réu primário", "Servidor público"], "explicacao": "Art. 318, I, do CPP."}, {"id": 10218, "materia": "ppen", "nivel": 2, "enunciado": "Nos crimes permanentes, como o sequestro, o agente:", "opcoes": ["Fica em flagrante enquanto durar a permanência", "Só pode ser preso por mandado judicial", "Fica em flagrante só nas primeiras 24 horas do crime", "Não pode ser preso em flagrante"], "explicacao": "Art. 303 do CPP."}, {"id": 10219, "materia": "ppen", "nivel": 2, "enunciado": "Pela Lei 12.830/2013, o indiciamento é ato privativo do:", "opcoes": ["Delegado de polícia", "Promotor de justiça", "Juiz da causa", "Escrivão de polícia"], "explicacao": "Art. 2º, § 6º, da Lei 12.830/2013."}, {"id": 10220, "materia": "ppen", "nivel": 2, "enunciado": "Pela Lei 12.830/2013, o inquérito em curso só pode ser avocado ou redistribuído por superior hierárquico:", "opcoes": ["Por despacho fundamentado, por interesse público", "A pedido verbal do investigado ou de seu advogado", "Sempre que o Ministério Público solicitar", "A qualquer tempo, sem precisar de justificativa"], "explicacao": "Art. 2º, § 4º, da Lei 12.830/2013."}, {"id": 10221, "materia": "ppen", "nivel": 2, "enunciado": "Pela Lei 9.296/1996, a interceptação telefônica só é admitida se houver indícios de autoria e o crime for punido com:", "opcoes": ["Reclusão", "Detenção", "Multa", "Prisão simples"], "explicacao": "Art. 2º, III, da Lei 9.296/1996."}, {"id": 10222, "materia": "ppen", "nivel": 2, "enunciado": "O réu que se oculta para não ser citado é citado:", "opcoes": ["Por hora certa", "Por edital", "Por telefone", "Por e-mail"], "explicacao": "Art. 362 do CPP."}, {"id": 10223, "materia": "ppen", "nivel": 2, "enunciado": "Se o réu citado por edital não comparece nem constitui advogado:", "opcoes": ["Suspendem-se o processo e o prazo prescricional", "O processo segue normalmente à revelia", "O juiz decreta a prisão preventiva automaticamente", "O processo é extinto sem julgamento"], "explicacao": "Art. 366 do CPP."}, {"id": 10224, "materia": "ppen", "nivel": 2, "enunciado": "A testemunha intimada que falta sem justo motivo pode ser:", "opcoes": ["Conduzida coercitivamente", "Presa preventivamente", "Processada por falso testemunho", "Dispensada sem consequência"], "explicacao": "Art. 218 do CPP."}, {"id": 10225, "materia": "ppen", "nivel": 2, "enunciado": "No procedimento comum, a resposta à acusação deve ser apresentada em:", "opcoes": ["10 dias", "5 dias", "15 dias", "20 dias"], "explicacao": "Art. 396 do CPP."}, {"id": 10226, "materia": "ppen", "nivel": 2, "enunciado": "Durante uma busca autorizada, a polícia encontra drogas que não eram o objeto do mandado. Segundo a jurisprudência, a apreensão é:", "opcoes": ["Válida, pelo encontro fortuito de provas", "Nula, pois não constava no mandado", "Válida só se o morador concordar", "Nula, salvo se houver flagrante de outro crime"], "explicacao": "Encontro fortuito (serendipidade) é admitido."}, {"id": 10227, "materia": "ppen", "nivel": 2, "enunciado": "Nos crimes que deixam vestígios, a falta do exame de corpo de delito, quando possível fazê-lo, gera:", "opcoes": ["Nulidade", "Mera irregularidade", "Absolvição automática", "Prisão do perito"], "explicacao": "Art. 564, III, b, do CPP."}, {"id": 10228, "materia": "ppen", "nivel": 2, "enunciado": "Diante da requisição do Ministério Público para instaurar inquérito, o delegado:", "opcoes": ["Deve instaurá-lo, salvo ordem manifestamente ilegal", "Pode recusá-la livremente, por ter autonomia funcional", "Precisa antes da autorização da vítima", "Só instaura se houver prisão em flagrante"], "explicacao": "Art. 5º, II, do CPP."}, {"id": 10229, "materia": "rl", "nivel": 2, "enunciado": "A contrapositiva de “Se é policial, então é servidor” é:", "opcoes": ["Se não é servidor, então não é policial", "Se é servidor, então é policial", "Se não é policial, então não é servidor", "Se é policial, então não é servidor"], "explicacao": "P → Q equivale a ¬Q → ¬P."}, {"id": 10230, "materia": "rl", "nivel": 2, "enunciado": "A negação de “Se ele estuda, então passa” é:", "opcoes": ["Ele estuda e não passa", "Ele não estuda e passa", "Se ele não estuda, não passa", "Ele não estuda ou passa"], "explicacao": "¬(P → Q) = P ∧ ¬Q."}, {"id": 10231, "materia": "rl", "nivel": 2, "enunciado": "Equivale a “Se chove, então levo guarda-chuva”:", "opcoes": ["Não chove ou levo guarda-chuva", "Chove e levo guarda-chuva", "Se levo guarda-chuva, então chove", "Não chove e não levo guarda-chuva"], "explicacao": "P → Q equivale a ¬P ∨ Q."}, {"id": 10232, "materia": "rl", "nivel": 2, "enunciado": "De quantas formas 4 agentes podem formar uma fila?", "opcoes": ["24", "16", "12", "8"], "explicacao": "4! = 24."}, {"id": 10233, "materia": "rl", "nivel": 2, "enunciado": "Quantas duplas diferentes podem ser formadas com 5 policiais?", "opcoes": ["10", "20", "25", "15"], "explicacao": "C(5,2) = 10."}, {"id": 10234, "materia": "rl", "nivel": 2, "enunciado": "Se “Algum agente é perito” é verdadeira, então é necessariamente verdadeira:", "opcoes": ["Algum perito é agente", "Todo agente é perito", "Nenhum perito é agente", "Todo perito é agente"], "explicacao": "A particular afirmativa pode ser invertida."}, {"id": 10235, "materia": "rl", "nivel": 2, "enunciado": "Num grupo de 50 agentes, 30 fazem musculação, 25 fazem corrida e 10 fazem os dois. Quantos não fazem nenhum dos dois?", "opcoes": ["5", "15", "10", "0"], "explicacao": "30 + 25 − 10 = 45; 50 − 45 = 5."}, {"id": 10236, "materia": "rl", "nivel": 2, "enunciado": "De quantas formas se escolhem um chefe e um subchefe entre 6 agentes?", "opcoes": ["30", "15", "36", "12"], "explicacao": "A ordem importa: 6 × 5 = 30."}, {"id": 10237, "materia": "rl", "nivel": 2, "enunciado": "Se “Todo perito é servidor” e “Nenhum servidor é corrupto”, então:", "opcoes": ["Nenhum perito é corrupto", "Algum perito é corrupto", "Todo servidor é perito", "Algum corrupto é perito"], "explicacao": "Os peritos estão dentro dos servidores, que não têm interseção com os corruptos."}, {"id": 10238, "materia": "adm", "nivel": 3, "enunciado": "A sindicância pode resultar em:", "opcoes": ["Arquivamento, advertência, suspensão até 30 dias ou PAD", "Demissão do servidor, sem necessidade de nenhum outro processo", "Cassação da aposentadoria do servidor investigado", "Destituição de cargo em comissão, de forma imediata"], "explicacao": "Art. 145 da Lei 8.112/1990."}, {"id": 10239, "materia": "adm", "nivel": 3, "enunciado": "O prazo da sindicância é de até:", "opcoes": ["30 dias, prorrogável por igual período", "60 dias, prorrogável por igual período", "10 dias, sem prorrogação", "90 dias, sem prorrogação"], "explicacao": "Art. 145, parágrafo único, da Lei 8.112/1990."}, {"id": 10240, "materia": "adm", "nivel": 3, "enunciado": "O afastamento preventivo do servidor durante o PAD pode durar:", "opcoes": ["Até 60 dias, prorrogável por igual prazo", "Até 30 dias, sem nenhuma possibilidade de prorrogação", "Até 120 dias, prorrogável uma única vez", "Até 90 dias, sem prorrogação"], "explicacao": "Art. 147 da Lei 8.112/1990, sem prejuízo da remuneração."}, {"id": 10241, "materia": "adm", "nivel": 3, "enunciado": "Na Lei 8.112/1990, a ação disciplinar para punir com advertência prescreve em:", "opcoes": ["180 dias", "2 anos", "5 anos", "1 ano"], "explicacao": "Art. 142, III, da Lei 8.112/1990."}, {"id": 10242, "materia": "adm", "nivel": 3, "enunciado": "A Lei 14.133/2021 prevê como modalidades de licitação:", "opcoes": ["Pregão, concorrência, concurso, leilão e diálogo competitivo", "Convite, tomada de preços, concorrência, concurso e leilão", "Pregão, convite, leilão, consulta e cotação eletrônica", "Concorrência, RDC, tomada de preços, pregão eletrônico e leilão"], "explicacao": "Art. 28 da Lei 14.133/2021."}, {"id": 10243, "materia": "adm", "nivel": 3, "enunciado": "As agências reguladoras são, em regra:", "opcoes": ["Autarquias em regime especial", "Empresas públicas", "Órgãos da administração direta", "Sociedades de economia mista"], "explicacao": "Têm maior autonomia que as autarquias comuns."}, {"id": 10244, "materia": "adm", "nivel": 3, "enunciado": "A desconcentração é:", "opcoes": ["Distribuir competências dentro da mesma pessoa jurídica", "A transferência de um serviço para outra pessoa jurídica", "A venda de empresas estatais para a iniciativa privada", "A extinção de órgãos públicos considerados inúteis"], "explicacao": "Cria órgãos, sem criar nova pessoa jurídica."}, {"id": 10245, "materia": "adm", "nivel": 3, "enunciado": "A descentralização ocorre quando o Estado:", "opcoes": ["Transfere a atividade para outra pessoa jurídica", "Cria órgãos internos dentro do mesmo ministério ou secretaria", "Divide setores dentro de uma secretaria", "Extingue autarquias e fundações"], "explicacao": "Ex.: criação de autarquia ou concessão de serviço."}, {"id": 10246, "materia": "adm", "nivel": 3, "enunciado": "O ato administrativo praticado por agente incompetente tem vício no elemento:", "opcoes": ["Competência (sujeito)", "Forma", "Motivo", "Objeto"], "explicacao": "Pode ser convalidado se a competência não for exclusiva."}, {"id": 10247, "materia": "const", "nivel": 3, "enunciado": "As guardas municipais destinam-se, pela Constituição, à proteção de:", "opcoes": ["Bens, serviços e instalações do município", "Fronteiras, portos e aeroportos do país", "Estabelecimentos penais estaduais", "Rodovias, ferrovias e hidrovias federais"], "explicacao": "Art. 144, § 8º, da CF."}, {"id": 10248, "materia": "const", "nivel": 3, "enunciado": "Entre as funções do Ministério Público está:", "opcoes": ["Controlar externamente a atividade policial", "Presidir o inquérito policial no lugar do delegado", "Julgar crimes comuns", "Expedir mandados de prisão"], "explicacao": "Art. 129, VII, da CF."}, {"id": 10249, "materia": "const", "nivel": 3, "enunciado": "A Defensoria Pública é incumbida da:", "opcoes": ["Orientação jurídica e defesa dos necessitados", "Acusação nos crimes de ação penal pública, no lugar do MP", "Investigação criminal nos estados", "Fiscalização das contas públicas"], "explicacao": "Art. 134 da CF."}, {"id": 10250, "materia": "const", "nivel": 3, "enunciado": "O estado de defesa é decretado pelo:", "opcoes": ["Presidente, ouvidos os Conselhos da República e de Defesa", "Congresso Nacional, por iniciativa própria, sem ouvir o Presidente", "Supremo Tribunal Federal, a pedido do Procurador-Geral", "Ministro da Defesa, com aval dos comandantes militares"], "explicacao": "Art. 136 da CF."}, {"id": 10251, "materia": "const", "nivel": 3, "enunciado": "O estado de defesa dura no máximo:", "opcoes": ["30 dias, prorrogável uma vez", "60 dias, sem prorrogação", "90 dias, prorrogável uma vez", "15 dias, sem prorrogação"], "explicacao": "Art. 136, § 2º, da CF."}, {"id": 10252, "materia": "const", "nivel": 3, "enunciado": "No estado de defesa, a prisão por crime contra o Estado não pode passar de:", "opcoes": ["10 dias, salvo autorização do Judiciário", "30 dias, sem possibilidade de prorrogação", "48 horas, salvo flagrante", "5 dias, prorrogáveis pelo Executivo"], "explicacao": "Art. 136, § 3º, III, da CF."}, {"id": 10253, "materia": "const", "nivel": 3, "enunciado": "A decretação do estado de sítio depende de:", "opcoes": ["Autorização prévia do Congresso Nacional", "Decisão do Supremo Tribunal Federal a pedido do Presidente", "Apenas decreto do Presidente", "Aprovação em plebiscito"], "explicacao": "Art. 137 da CF."}, {"id": 10254, "materia": "const", "nivel": 3, "enunciado": "A extradição de brasileiro nato é:", "opcoes": ["Proibida", "Permitida por tráfico", "Permitida por crime comum", "Permitida com tratado"], "explicacao": "Art. 5º, LI, da CF."}, {"id": 10255, "materia": "const", "nivel": 3, "enunciado": "O brasileiro naturalizado pode ser extraditado por:", "opcoes": ["Crime comum anterior à naturalização ou tráfico de drogas", "Qualquer crime, a qualquer tempo, se houver tratado de extradição", "Crime político cometido depois da naturalização", "Nenhum crime, pois tem os mesmos direitos do nato"], "explicacao": "Art. 5º, LI, da CF."}, {"id": 10256, "materia": "const", "nivel": 3, "enunciado": "Não se concede extradição de estrangeiro por:", "opcoes": ["Crime político ou de opinião", "Tráfico internacional de drogas", "Homicídio doloso", "Terrorismo"], "explicacao": "Art. 5º, LII, da CF."}, {"id": 10257, "materia": "const", "nivel": 3, "enunciado": "A segurança viária, incluída pela EC 82/2014, compreende a educação, a engenharia e a:", "opcoes": ["Fiscalização de trânsito", "Arrecadação de multas de trânsito", "Construção de presídios", "Defesa civil"], "explicacao": "Art. 144, § 10, da CF."}, {"id": 10258, "materia": "dh", "nivel": 3, "enunciado": "Pela Convenção Americana, a pena de morte, onde ainda existir, não pode ser aplicada a quem, na data do crime, tinha:", "opcoes": ["Menos de 18 ou mais de 70 anos", "Menos de 21 ou mais de 60 anos", "Menos de 16 ou mais de 65 anos", "Menos de 18 ou mais de 80 anos"], "explicacao": "Art. 4.5 da Convenção Americana."}, {"id": 10259, "materia": "dh", "nivel": 3, "enunciado": "Pela Convenção Americana, os países que aboliram a pena de morte:", "opcoes": ["Não podem restabelecê-la", "Podem restabelecê-la por lei", "Podem restabelecê-la por plebiscito", "Podem aplicá-la só a terroristas"], "explicacao": "Art. 4.3 da Convenção Americana."}, {"id": 10260, "materia": "dh", "nivel": 3, "enunciado": "Os direitos humanos de primeira geração (dimensão) são os:", "opcoes": ["Civis e políticos", "Sociais e econômicos", "Difusos, como o meio ambiente", "Ligados à biotecnologia"], "explicacao": "Ligados à liberdade."}, {"id": 10261, "materia": "dh", "nivel": 3, "enunciado": "O direito ao meio ambiente equilibrado é exemplo de direito de:", "opcoes": ["Terceira geração", "Primeira geração", "Segunda geração", "Nenhuma geração"], "explicacao": "Direitos de solidariedade ou fraternidade."}, {"id": 10262, "materia": "dh", "nivel": 3, "enunciado": "A Corte Interamericana condenou o Brasil, no caso Herzog (2018), por:", "opcoes": ["Não investigar nem punir a tortura e morte do jornalista", "Trabalho escravo em fazenda no sul do Pará, em 1988", "Violência em operações policiais no Rio", "Morte de paciente em clínica psiquiátrica no interior do Ceará"], "explicacao": "Vladimir Herzog morreu em 1975 no DOI-Codi de São Paulo."}, {"id": 10263, "materia": "igual", "nivel": 3, "enunciado": "Impedir o acesso a estabelecimento comercial por preconceito de raça tem pena de:", "opcoes": ["Reclusão de 1 a 3 anos", "Detenção de 3 meses a 1 ano", "Reclusão de 2 a 5 anos", "Apenas multa"], "explicacao": "Art. 5º da Lei 7.716/1989."}, {"id": 10264, "materia": "igual", "nivel": 3, "enunciado": "Praticar ou incitar a discriminação racial pelos meios de comunicação ou redes sociais tem pena de:", "opcoes": ["Reclusão de 2 a 5 anos e multa", "Reclusão de 1 a 3 anos e multa", "Detenção de 6 meses a 1 ano", "Apenas multa"], "explicacao": "Art. 20, § 2º, da Lei 7.716/1989."}, {"id": 10265, "materia": "igual", "nivel": 3, "enunciado": "Os efeitos da condenação pela Lei 7.716/1989, como a perda do cargo público:", "opcoes": ["Não são automáticos e devem ser declarados na sentença", "São automáticos em qualquer caso, inclusive na transação penal", "São proibidos pela Constituição", "São aplicados pelo chefe do órgão"], "explicacao": "Art. 18 da Lei 7.716/1989."}, {"id": 10266, "materia": "inf", "nivel": 3, "enunciado": "Um ataque DDoS busca:", "opcoes": ["Derrubar um serviço com excesso de acessos", "Roubar senhas por meio de e-mails falsos enviados em massa", "Criptografar arquivos e pedir resgate", "Registrar as teclas digitadas"], "explicacao": "Negação de serviço distribuída."}, {"id": 10267, "materia": "inf", "nivel": 3, "enunciado": "No Excel, =SE(A1>=7;\"Aprovado\";\"Reprovado\"), com A1 igual a 7, retorna:", "opcoes": ["Aprovado", "Reprovado", "#VALOR!", "7"], "explicacao": "7 é maior ou igual a 7."}, {"id": 10268, "materia": "inf", "nivel": 3, "enunciado": "No Excel, a função PROCV serve para:", "opcoes": ["Procurar um valor numa tabela e trazer dado da mesma linha", "Somar os valores de uma coluna que atendem a uma condição dada", "Contar as células vazias", "Arredondar números decimais"], "explicacao": "Procura vertical."}, {"id": 10269, "materia": "inf", "nivel": 3, "enunciado": "Na computação em nuvem, o modelo em que o usuário usa um software pronto pela internet, como um e-mail on-line, é o:", "opcoes": ["SaaS", "IaaS", "PaaS", "LAN"], "explicacao": "Software como serviço."}, {"id": 10270, "materia": "inf", "nivel": 3, "enunciado": "O backup diferencial copia:", "opcoes": ["O que mudou desde o último backup completo", "Só o que mudou desde o último backup de qualquer tipo", "Todos os arquivos, sempre", "Só os arquivos do sistema"], "explicacao": "O incremental copia o que mudou desde o último backup de qualquer tipo."}, {"id": 10271, "materia": "leg", "nivel": 3, "enunciado": "Desde a Lei 13.964/2019, a progressão de regime nos crimes hediondos segue:", "opcoes": ["Os percentuais do art. 112 da LEP", "Sempre 2/5 da pena, se primário", "Sempre 1/6 da pena, como os demais crimes", "A proibição total de progressão de regime"], "explicacao": "Art. 112 da LEP."}, {"id": 10272, "materia": "leg", "nivel": 3, "enunciado": "Pela LEP, o primário condenado por crime sem violência ou grave ameaça progride após cumprir:", "opcoes": ["16% da pena", "20% da pena", "25% da pena", "30% da pena"], "explicacao": "Art. 112, I, da LEP."}, {"id": 10273, "materia": "leg", "nivel": 3, "enunciado": "Pela LEP, o reincidente em crime hediondo ou equiparado progride após cumprir:", "opcoes": ["60% da pena", "40% da pena", "50% da pena", "70% da pena"], "explicacao": "Art. 112, VII, da LEP."}, {"id": 10274, "materia": "leg", "nivel": 3, "enunciado": "Pela LEP, o primário condenado por crime hediondo com resultado morte progride após cumprir:", "opcoes": ["50% da pena, sem livramento condicional", "40% da pena, com direito a livramento", "60% da pena, com direito a livramento condicional", "30% da pena, sem direito a livramento"], "explicacao": "Art. 112, VI, a, da LEP."}, {"id": 10275, "materia": "leg", "nivel": 3, "enunciado": "Pela LEP, a remição pelo trabalho é de:", "opcoes": ["1 dia de pena a cada 3 dias de trabalho", "1 dia de pena a cada 2 dias de trabalho", "1 dia de pena a cada 5 dias de trabalho", "2 dias de pena a cada 3 dias de trabalho"], "explicacao": "Art. 126, § 1º, II, da LEP."}, {"id": 10276, "materia": "leg", "nivel": 3, "enunciado": "Pela LEP, a remição pelo estudo é de 1 dia de pena a cada:", "opcoes": ["12 horas de estudo, em pelo menos 3 dias", "8 horas de estudo em um único dia", "24 horas de aula, em qualquer período", "6 horas de leitura, comprovadas por resumo"], "explicacao": "Art. 126, § 1º, I, da LEP."}, {"id": 10277, "materia": "leg", "nivel": 3, "enunciado": "Desde a Lei 13.964/2019, o regime disciplinar diferenciado dura até:", "opcoes": ["2 anos, podendo repetir-se por nova falta grave", "360 dias, sem possibilidade de nova aplicação ao preso", "1 ano, sem possibilidade de prorrogação", "6 meses, renováveis uma única vez"], "explicacao": "Art. 52, I, da LEP."}, {"id": 10278, "materia": "leg", "nivel": 3, "enunciado": "Integrar organização criminosa tem pena de:", "opcoes": ["Reclusão de 3 a 8 anos e multa", "Reclusão de 1 a 3 anos", "Reclusão de 5 a 15 anos e multa", "Detenção de 2 a 4 anos"], "explicacao": "Art. 2º da Lei 12.850/2013."}, {"id": 10279, "materia": "leg", "nivel": 3, "enunciado": "A associação criminosa do Código Penal (art. 288) exige:", "opcoes": ["3 ou mais pessoas", "4 ou mais pessoas", "2 ou mais pessoas", "5 ou mais pessoas"], "explicacao": "Art. 288 do CP. A organização criminosa exige 4 ou mais."}, {"id": 10280, "materia": "leg", "nivel": 3, "enunciado": "Desde a Lei 12.683/2012, o crime antecedente da lavagem de dinheiro pode ser:", "opcoes": ["Qualquer infração penal", "Apenas o tráfico de drogas", "Apenas crimes contra a administração", "Apenas crimes hediondos"], "explicacao": "Art. 1º da Lei 9.613/1998."}, {"id": 10281, "materia": "leg", "nivel": 3, "enunciado": "Na forma básica, o homicídio culposo na direção de veículo tem pena de:", "opcoes": ["Detenção de 2 a 4 anos e suspensão da habilitação", "Reclusão de 5 a 8 anos e cassação definitiva da habilitação", "Detenção de 1 a 3 anos, sem efeito sobre a habilitação", "Reclusão de 2 a 6 anos e multa"], "explicacao": "Art. 302 do CTB."}, {"id": 10282, "materia": "leg", "nivel": 3, "enunciado": "Pelo CTB, se o condutor presta pronto e integral socorro à vítima do acidente:", "opcoes": ["Não se impõe prisão em flagrante nem fiança", "A prisão em flagrante continua obrigatória, sem fiança", "A fiança é fixada em dobro", "Nenhum benefício é previsto"], "explicacao": "Art. 301 do CTB."}, {"id": 10283, "materia": "leg", "nivel": 3, "enunciado": "Pela Lei 12.850/2013, a pena aumenta de 1/6 a 2/3 se a organização criminosa contar com:", "opcoes": ["A participação de criança ou adolescente", "Integrantes primários", "Apenas brasileiros natos", "Membros com mais de 60 anos de idade, como líderes"], "explicacao": "Art. 2º, § 4º, I, da Lei 12.850/2013."}, {"id": 10284, "materia": "leg", "nivel": 3, "enunciado": "Na colaboração premiada, o juiz pode conceder:", "opcoes": ["Perdão judicial, redução de até 2/3 ou substituição", "Absolvição sumária em qualquer caso, sem condições, a pedido", "Apenas redução de 1/6", "Indenização ao colaborador"], "explicacao": "Art. 4º da Lei 12.850/2013."}, {"id": 10285, "materia": "leg", "nivel": 3, "enunciado": "Pela Lei 9.099/1995, a transação penal é proposta pelo:", "opcoes": ["Ministério Público", "Juiz", "Delegado", "Defensor"], "explicacao": "Art. 76 da Lei 9.099/1995."}, {"id": 10286, "materia": "leg", "nivel": 3, "enunciado": "Na suspensão condicional do processo, o período de prova é de:", "opcoes": ["2 a 4 anos", "1 a 2 anos", "4 a 6 anos", "6 meses a 1 ano"], "explicacao": "Art. 89 da Lei 9.099/1995."}, {"id": 10287, "materia": "leg", "nivel": 3, "enunciado": "Pela Lei 9.099/1995, o autor do fato que assume o compromisso de comparecer ao juizado:", "opcoes": ["Não será preso em flagrante nem pagará fiança", "Será preso em flagrante normalmente pelo delegado", "Pagará fiança fixada pelo delegado", "Ficará preso até a audiência"], "explicacao": "Art. 69, parágrafo único, da Lei 9.099/1995."}, {"id": 10288, "materia": "ml", "nivel": 3, "enunciado": "A esganadura é a constrição do pescoço feita:", "opcoes": ["Pelas mãos", "Por laço acionado pelo peso do corpo", "Por laço acionado por força externa", "Por objeto pesado sobre o tórax"], "explicacao": "Deixa marcas de unhas e dedos."}, {"id": 10289, "materia": "ml", "nivel": 3, "enunciado": "A sufocação direta ocorre, por exemplo, por:", "opcoes": ["Oclusão da boca e do nariz", "Compressão do tórax", "Constrição do pescoço", "Submersão em líquido"], "explicacao": "A compressão do tórax é sufocação indireta."}, {"id": 10290, "materia": "ml", "nivel": 3, "enunciado": "A saponificação (adipocera) é fenômeno conservador que ocorre em ambiente:", "opcoes": ["Úmido e com pouco oxigênio", "Seco e quente", "Muito frio e seco", "Arejado e ensolarado"], "explicacao": "Comum em corpos submersos ou em solo argiloso."}, {"id": 10291, "materia": "ml", "nivel": 3, "enunciado": "A mumificação é favorecida por ambiente:", "opcoes": ["Quente, seco e arejado", "Úmido e fechado", "Submerso em água", "Gelado e úmido"], "explicacao": "Desidratação rápida do corpo."}, {"id": 10292, "materia": "ml", "nivel": 3, "enunciado": "As figuras de Lichtenberg, em forma de árvore na pele, indicam lesão por:", "opcoes": ["Raio", "Afogamento", "Envenenamento", "Fogo"], "explicacao": "Fulguração."}, {"id": 10293, "materia": "ml", "nivel": 3, "enunciado": "A marca elétrica de Jellinek é típica de lesão por:", "opcoes": ["Corrente elétrica", "Raio", "Arma de fogo", "Calor radiante"], "explicacao": "Eletroplessão, no ponto de entrada da corrente."}, {"id": 10294, "materia": "ml", "nivel": 3, "enunciado": "Em restos esqueletizados, o DNA para identificação costuma ser extraído de:", "opcoes": ["Ossos longos e dentes", "Cabelo sem raiz", "Unhas soltas", "Pele ressecada"], "explicacao": "São os tecidos que melhor preservam o DNA."}, {"id": 10295, "materia": "ml", "nivel": 3, "enunciado": "Na morte por afogamento, a presença de água e plâncton nos pulmões indica que a vítima:", "opcoes": ["Estava viva ao cair na água", "Já estava morta ao cair na água", "Morreu de causa natural", "Foi envenenada"], "explicacao": "Sinal de afogamento em vida."}, {"id": 10296, "materia": "ml", "nivel": 3, "enunciado": "Nos ferimentos de defesa, as lesões costumam aparecer:", "opcoes": ["Nas mãos e nos antebraços", "Nas costas e nos ombros", "Na sola dos pés", "Na nuca"], "explicacao": "A vítima tenta se proteger do agressor."}, {"id": 10297, "materia": "pcd", "nivel": 3, "enunciado": "Pela LBI, discriminar pessoa em razão da deficiência tem pena de:", "opcoes": ["Reclusão de 1 a 3 anos e multa", "Detenção de 6 meses a 1 ano", "Reclusão de 2 a 5 anos e multa", "Apenas multa"], "explicacao": "Art. 88 da LBI."}, {"id": 10298, "materia": "pcd", "nivel": 3, "enunciado": "Pela LBI, apropriar-se de bens ou benefícios da pessoa com deficiência tem pena de:", "opcoes": ["Reclusão de 1 a 4 anos e multa", "Detenção de 1 a 3 anos e multa", "Reclusão de 2 a 8 anos e multa", "Apenas multa"], "explicacao": "Art. 89 da LBI."}, {"id": 10299, "materia": "pcd", "nivel": 3, "enunciado": "Pela LBI, abandonar pessoa com deficiência em hospital ou casa de saúde tem pena de:", "opcoes": ["Reclusão de 6 meses a 3 anos e multa", "Detenção de 1 a 6 meses ou multa, apenas", "Reclusão de 2 a 5 anos e multa", "Apenas multa"], "explicacao": "Art. 90 da LBI."}, {"id": 10300, "materia": "pen", "nivel": 3, "enunciado": "Pelo Código Penal, a pena de multa varia de:", "opcoes": ["10 a 360 dias-multa", "5 a 180 dias-multa", "30 a 365 dias-multa", "1 a 100 dias-multa"], "explicacao": "Art. 49 do CP."}, {"id": 10301, "materia": "pen", "nivel": 3, "enunciado": "O condenado não reincidente a pena superior a 8 anos começa a cumpri-la no regime:", "opcoes": ["Fechado", "Semiaberto", "Aberto", "Domiciliar"], "explicacao": "Art. 33, § 2º, a, do CP."}, {"id": 10302, "materia": "pen", "nivel": 3, "enunciado": "O condenado não reincidente a pena superior a 4 anos e não excedente a 8 pode começar no regime:", "opcoes": ["Semiaberto", "Fechado, obrigatoriamente", "Aberto", "Domiciliar"], "explicacao": "Art. 33, § 2º, b, do CP."}, {"id": 10303, "materia": "pen", "nivel": 3, "enunciado": "Em crime doloso sem violência ou grave ameaça, a pena de prisão pode ser substituída por restritiva de direitos se não for superior a:", "opcoes": ["4 anos", "2 anos", "6 anos", "8 anos"], "explicacao": "Art. 44, I, do CP."}, {"id": 10304, "materia": "pen", "nivel": 3, "enunciado": "Para efeito de reincidência, não prevalece a condenação anterior se, entre o fim da pena e o novo crime, passou período superior a:", "opcoes": ["5 anos", "3 anos", "10 anos", "2 anos"], "explicacao": "Art. 64, I, do CP."}, {"id": 10305, "materia": "pen", "nivel": 3, "enunciado": "O livramento condicional do condenado não reincidente em crime doloso e de bons antecedentes exige cumprir mais de:", "opcoes": ["Um terço da pena", "Metade da pena", "Dois terços da pena", "Um sexto da pena"], "explicacao": "Art. 83, I, do CP."}, {"id": 10306, "materia": "pen", "nivel": 3, "enunciado": "No crime continuado simples, aplica-se a pena de um só dos crimes, aumentada de:", "opcoes": ["Um sexto a dois terços", "Um sexto até metade", "Um terço até o dobro", "Metade até dois terços"], "explicacao": "Art. 71, caput, do CP."}, {"id": 10307, "materia": "pen", "nivel": 3, "enunciado": "No concurso formal próprio, aplica-se a pena mais grave, aumentada de:", "opcoes": ["Um sexto até metade", "Um sexto a dois terços", "Um terço até o dobro", "Metade até o triplo"], "explicacao": "Art. 70 do CP."}, {"id": 10308, "materia": "pen", "nivel": 3, "enunciado": "A prescrição antes do trânsito em julgado, para crime com pena máxima acima de 2 e até 4 anos, ocorre em:", "opcoes": ["8 anos", "4 anos", "12 anos", "6 anos"], "explicacao": "Art. 109, IV, do CP."}, {"id": 10309, "materia": "pen", "nivel": 3, "enunciado": "Os prazos de prescrição caem pela metade se o agente, na data do crime, era menor de:", "opcoes": ["21 anos", "18 anos", "25 anos", "16 anos"], "explicacao": "Art. 115 do CP. Também se tiver mais de 70 anos na data da sentença."}, {"id": 10310, "materia": "pen", "nivel": 3, "enunciado": "Desde a Lei 13.964/2019, o tempo máximo de cumprimento das penas de prisão é de:", "opcoes": ["40 anos", "30 anos", "50 anos", "35 anos"], "explicacao": "Art. 75 do CP."}, {"id": 10311, "materia": "pen", "nivel": 3, "enunciado": "Quem cumpre ordem não manifestamente ilegal de superior hierárquico:", "opcoes": ["Fica isento, punindo-se só quem deu a ordem", "Responde junto com quem deu a ordem", "Responde sozinho pelo crime, como autor direto", "Responde por crime culposo"], "explicacao": "Art. 22 do CP: obediência hierárquica."}, {"id": 10312, "materia": "pen", "nivel": 3, "enunciado": "O agente que, no furto, emprega chave falsa comete:", "opcoes": ["Furto qualificado", "Furto privilegiado", "Roubo impróprio", "Estelionato"], "explicacao": "Art. 155, § 4º, III, do CP."}, {"id": 10313, "materia": "pen", "nivel": 3, "enunciado": "Uma pessoa recebe objeto que, pela desproporção entre o valor e o preço, deveria presumir ser de origem criminosa. Ela comete:", "opcoes": ["Receptação culposa", "Receptação dolosa", "Favorecimento real", "Fato atípico"], "explicacao": "Art. 180, § 3º, do CP."}, {"id": 10314, "materia": "pen", "nivel": 3, "enunciado": "Rita, funcionária pública, desvia para uma ONG da família verba que administrava no órgão. Ela comete:", "opcoes": ["Peculato-desvio", "Peculato-furto", "Concussão", "Prevaricação"], "explicacao": "Art. 312, caput, segunda parte, do CP: desviar em proveito próprio ou alheio."}, {"id": 10315, "materia": "pen", "nivel": 3, "enunciado": "Um médico de hospital público exige dinheiro da família para fazer a cirurgia pelo SUS. Ele comete:", "opcoes": ["Concussão", "Corrupção ativa", "Estelionato", "Extorsão"], "explicacao": "Art. 316 do CP. Ele é funcionário público para fins penais (art. 327)."}, {"id": 10316, "materia": "port", "nivel": 3, "enunciado": "Em “A confiança na polícia aumentou”, o termo “na polícia” é:", "opcoes": ["Complemento nominal", "Adjunto adnominal", "Objeto indireto", "Adjunto adverbial"], "explicacao": "Completa o sentido do nome “confiança”, com valor passivo."}, {"id": 10317, "materia": "port", "nivel": 3, "enunciado": "Em “O relatório do perito chegou”, o termo “do perito” é:", "opcoes": ["Adjunto adnominal", "Complemento nominal", "Objeto indireto", "Agente da passiva"], "explicacao": "Indica posse/autoria: o perito fez o relatório."}, {"id": 10318, "materia": "port", "nivel": 3, "enunciado": "Em “O suspeito foi preso pelos agentes”, o termo “pelos agentes” é:", "opcoes": ["Agente da passiva", "Objeto indireto", "Adjunto adverbial de modo", "Complemento nominal"], "explicacao": "Pratica a ação na voz passiva analítica."}, {"id": 10319, "materia": "port", "nivel": 3, "enunciado": "Assinale a frase em que a crase é obrigatória:", "opcoes": ["Refiro-me à investigadora.", "Começou a chover cedo.", "Fui a Brasília ontem.", "Ficou frente a frente com ele."], "explicacao": "“Referir-se a” + “a investigadora”."}, {"id": 10320, "materia": "port", "nivel": 3, "enunciado": "Há crase facultativa em:", "opcoes": ["Entreguei o laudo à sua chefe.", "Fui à delegacia central de manhã.", "Às vezes ele chega tarde.", "Saiu às pressas do local."], "explicacao": "Antes de pronome possessivo feminino, a crase é facultativa."}, {"id": 10321, "materia": "port", "nivel": 3, "enunciado": "A voz passiva analítica de “O juiz expediu o mandado” é:", "opcoes": ["O mandado foi expedido pelo juiz.", "Expediu-se o mandado.", "O juiz foi expedido pelo mandado.", "O mandado expediu-se pelo juiz."], "explicacao": "Ser + particípio + agente da passiva."}, {"id": 10322, "materia": "port", "nivel": 3, "enunciado": "Em “Chegou o laudo e as fotos”, a concordância do verbo:", "opcoes": ["Está correta, concordando com o núcleo mais próximo", "Está errada, pois o verbo deveria ir ao plural", "É errada, pois com sujeito posposto o plural é obrigatório", "Só seria possível com sujeito simples"], "explicacao": "Com sujeito composto posposto, admite-se a concordância com o mais próximo."}, {"id": 10323, "materia": "ppen", "nivel": 3, "enunciado": "O procedimento comum ordinário se aplica a crimes com pena máxima igual ou superior a:", "opcoes": ["4 anos", "2 anos", "8 anos", "1 ano"], "explicacao": "Art. 394, § 1º, I, do CPP."}, {"id": 10324, "materia": "ppen", "nivel": 3, "enunciado": "No procedimento sumário, a audiência de instrução deve ocorrer em até:", "opcoes": ["30 dias", "60 dias", "15 dias", "90 dias"], "explicacao": "Art. 531 do CPP. No ordinário, o prazo é de 60 dias (art. 400)."}, {"id": 10325, "materia": "ppen", "nivel": 3, "enunciado": "No procedimento ordinário, cada parte pode arrolar até:", "opcoes": ["8 testemunhas", "5 testemunhas", "3 testemunhas", "10 testemunhas"], "explicacao": "Art. 401 do CPP. No sumário, são 5."}, {"id": 10326, "materia": "ppen", "nivel": 3, "enunciado": "Após a resposta à acusação, o juiz absolve sumariamente o réu, por exemplo, quando:", "opcoes": ["O fato evidentemente não constitui crime", "Houver dúvida razoável sobre a autoria", "O réu for primário e de bons antecedentes", "A vítima desistir de prosseguir no processo"], "explicacao": "Art. 397, III, do CPP."}, {"id": 10327, "materia": "ppen", "nivel": 3, "enunciado": "Na primeira fase do júri, o juiz pode pronunciar, impronunciar, desclassificar ou:", "opcoes": ["Absolver sumariamente", "Condenar o réu", "Aplicar a pena", "Arquivar o inquérito"], "explicacao": "Arts. 413 a 419 do CPP."}, {"id": 10328, "materia": "ppen", "nivel": 3, "enunciado": "O Conselho de Sentença do júri é formado por:", "opcoes": ["7 jurados", "12 jurados", "5 jurados", "25 jurados"], "explicacao": "Art. 447 do CPP."}, {"id": 10329, "materia": "ppen", "nivel": 3, "enunciado": "Para instalar a sessão do júri, devem comparecer, no mínimo:", "opcoes": ["15 jurados", "7 jurados", "25 jurados", "21 jurados"], "explicacao": "Art. 463 do CPP."}, {"id": 10330, "materia": "ppen", "nivel": 3, "enunciado": "No júri, cada parte pode recusar sem motivo até:", "opcoes": ["3 jurados", "5 jurados", "2 jurados", "7 jurados"], "explicacao": "Art. 468 do CPP: recusas peremptórias."}, {"id": 10331, "materia": "ppen", "nivel": 3, "enunciado": "A revisão criminal pode ser pedida:", "opcoes": ["A qualquer tempo, mesmo depois de extinta a pena", "Em até 2 anos contados do trânsito em julgado da condenação", "Somente enquanto o réu cumpre a pena", "Apenas pelo Ministério Público"], "explicacao": "Art. 622 do CPP."}, {"id": 10332, "materia": "ppen", "nivel": 3, "enunciado": "A revisão criminal só é admitida em favor:", "opcoes": ["Do condenado", "Da acusação", "Da vítima", "Do condenado e da acusação"], "explicacao": "Não existe revisão criminal contra o réu."}, {"id": 10333, "materia": "ppen", "nivel": 3, "enunciado": "Cabe recurso em sentido estrito contra a decisão que:", "opcoes": ["Pronuncia o réu", "Condena o réu no júri", "Absolve o réu no rito comum", "Julga a apelação"], "explicacao": "Art. 581, IV, do CPP."}, {"id": 10334, "materia": "ppen", "nivel": 3, "enunciado": "Pela vedação da reformatio in pejus, em recurso exclusivo da defesa:", "opcoes": ["A situação do réu não pode ser piorada", "O tribunal pode aumentar a pena", "O MP pode pedir pena maior nas contrarrazões", "O réu perde o direito a novo recurso"], "explicacao": "Art. 617 do CPP."}, {"id": 10335, "materia": "ppen", "nivel": 3, "enunciado": "Pela Lei 12.850/2013, nenhuma sentença condenatória pode se basear apenas:", "opcoes": ["Nas declarações do colaborador", "Na confissão do réu", "No laudo pericial", "Na prova testemunhal de um só policial"], "explicacao": "Art. 4º, § 16, da Lei 12.850/2013."}, {"id": 10336, "materia": "ppen", "nivel": 3, "enunciado": "A infiltração de agentes policiais em organização criminosa depende de:", "opcoes": ["Autorização judicial circunstanciada e sigilosa", "Ordem escrita e reservada do delegado-geral de polícia", "Requisição do governador do estado", "Consentimento formal do Ministério Público"], "explicacao": "Art. 10 da Lei 12.850/2013."}, {"id": 10337, "materia": "ppen", "nivel": 3, "enunciado": "Na Lei 12.850/2013, a ação controlada consiste em:", "opcoes": ["Retardar a ação policial para agir no momento mais eficaz", "Infiltrar um agente de polícia na organização criminosa", "Interceptar as comunicações telefônicas dos investigados do grupo", "Induzir o investigado a cometer o crime para prendê-lo"], "explicacao": "Art. 8º da Lei 12.850/2013."}, {"id": 10338, "materia": "ppen", "nivel": 3, "enunciado": "Na ação penal privada subsidiária da pública, a queixa é cabível quando:", "opcoes": ["O MP não oferece denúncia no prazo legal", "O MP pede o arquivamento do inquérito", "O juiz rejeita a denúncia", "A vítima discorda da pena pedida pelo MP"], "explicacao": "Art. 29 do CPP e art. 5º, LIX, da CF."}, {"id": 10339, "materia": "ppen", "nivel": 3, "enunciado": "O perdão do ofendido, na ação penal privada, só produz efeito se:", "opcoes": ["For aceito pelo querelado", "For dado antes da queixa", "For homologado pelo MP", "For publicado em jornal"], "explicacao": "Art. 51 do CPP e art. 106, III, do CP."}, {"id": 10340, "materia": "ppen", "nivel": 3, "enunciado": "A renúncia ao direito de queixa ocorre:", "opcoes": ["Antes de iniciada a ação penal privada", "Depois da sentença condenatória de primeiro grau", "Durante a instrução", "Só no júri"], "explicacao": "Arts. 49 e 50 do CPP. Depois de iniciada a ação, fala-se em perdão."}, {"id": 10341, "materia": "ppen", "nivel": 3, "enunciado": "Nos crimes de ação privada, a renúncia em relação a um dos autores:", "opcoes": ["A todos se estende", "Vale só para ele", "Exige aceitação", "É proibida"], "explicacao": "Art. 49 do CPP: princípio da indivisibilidade."}, {"id": 10342, "materia": "ppen", "nivel": 3, "enunciado": "A queixa-crime pode ser aditada pelo Ministério Público no prazo de:", "opcoes": ["3 dias", "5 dias", "10 dias", "15 dias"], "explicacao": "Art. 46, § 2º, do CPP."}, {"id": 10343, "materia": "rl", "nivel": 3, "enunciado": "Com 6 agentes, quantas equipes de 3 podem ser formadas?", "opcoes": ["20", "120", "18", "60"], "explicacao": "C(6,3) = 20."}, {"id": 10344, "materia": "rl", "nivel": 3, "enunciado": "A proposição P → Q é equivalente a:", "opcoes": ["¬Q → ¬P", "Q → P", "¬P → ¬Q", "P ∧ ¬Q"], "explicacao": "Contrapositiva."}, {"id": 10345, "materia": "rl", "nivel": 3, "enunciado": "Se “Nenhum A é B” é verdadeira, então também é verdadeira:", "opcoes": ["Nenhum B é A", "Todo A é B", "Algum A é B", "Todo B é A"], "explicacao": "A proposição universal negativa pode ser invertida."}, {"id": 10346, "materia": "rl", "nivel": 3, "enunciado": "R$ 1.000 a juros simples de 2% ao mês, por 5 meses, rendem juros de:", "opcoes": ["R$ 100", "R$ 50", "R$ 104,08", "R$ 200"], "explicacao": "1.000 × 0,02 × 5 = 100."}, {"id": 10347, "materia": "rl", "nivel": 3, "enunciado": "Uma senha tem 3 dígitos distintos de 0 a 9. Quantas senhas são possíveis?", "opcoes": ["720", "1.000", "504", "120"], "explicacao": "10 × 9 × 8 = 720."}, {"id": 10348, "materia": "rl", "nivel": 3, "enunciado": "A probabilidade de, ao lançar 3 moedas, sair pelo menos uma cara é:", "opcoes": ["7/8", "1/8", "3/8", "1/2"], "explicacao": "1 − (1/2)³ = 7/8."}, {"id": 10349, "materia": "rl", "nivel": 3, "enunciado": "Um preço sobe 20% e depois cai 20%. Em relação ao preço inicial, ele fica:", "opcoes": ["4% menor", "Igual", "4% maior", "2% menor"], "explicacao": "1,2 × 0,8 = 0,96."}, {"id": 10350, "materia": "adm", "nivel": 4, "enunciado": "Pela teoria do risco administrativo, a responsabilidade do Estado pode ser afastada ou reduzida por:", "opcoes": ["Culpa exclusiva da vítima, caso fortuito ou força maior", "Ausência de dolo do agente público que causou o dano ao particular", "Ausência de culpa do agente público que causou o dano", "Falta de verba no orçamento para pagar a indenização"], "explicacao": "Excludentes do nexo causal."}, {"id": 10351, "materia": "adm", "nivel": 4, "enunciado": "Segundo o STF, a morte de preso sob custódia do Estado gera responsabilidade:", "opcoes": ["Objetiva, por violação do dever de proteção", "Subjetiva, exigindo prova de culpa do agente", "Nenhuma, se o preso tinha condenação", "Só se o agente for condenado criminalmente"], "explicacao": "Tema 592 do STF (RE 841.526)."}, {"id": 10352, "materia": "adm", "nivel": 4, "enunciado": "Segundo o STF, a ação de ressarcimento ao erário por ato doloso de improbidade é:", "opcoes": ["Imprescritível", "Prescritível em 5 anos", "Prescritível em 10 anos", "Prescritível em 20 anos"], "explicacao": "Tema 897 do STF."}, {"id": 10353, "materia": "adm", "nivel": 4, "enunciado": "Recondução é o retorno do servidor estável ao cargo anterior por:", "opcoes": ["Inabilitação em estágio probatório ou reintegração do anterior ocupante", "Reversão da aposentadoria por invalidez, depois de nova perícia médica", "Anulação judicial da demissão, com ressarcimento das vantagens", "Extinção do cargo que ocupava, com retorno da disponibilidade"], "explicacao": "Art. 29 da Lei 8.112/1990."}, {"id": 10354, "materia": "adm", "nivel": 4, "enunciado": "Aproveitamento é o retorno à atividade do servidor:", "opcoes": ["Em disponibilidade", "Aposentado", "Demitido", "Removido"], "explicacao": "Art. 30 da Lei 8.112/1990."}, {"id": 10355, "materia": "adm", "nivel": 4, "enunciado": "Prédios de repartições públicas, como delegacias, são bens públicos:", "opcoes": ["De uso especial", "De uso comum do povo", "Dominicais", "Particulares afetados"], "explicacao": "Art. 99, II, do Código Civil."}, {"id": 10356, "materia": "adm", "nivel": 4, "enunciado": "Na requisição administrativa, em caso de iminente perigo público, o proprietário tem direito a:", "opcoes": ["Indenização posterior, se houver dano", "Indenização prévia e em dinheiro", "Nenhuma indenização, em qualquer caso", "Indenização em títulos da dívida"], "explicacao": "Art. 5º, XXV, da CF."}, {"id": 10357, "materia": "adm", "nivel": 4, "enunciado": "A convalidação de ato administrativo é possível quando o vício for:", "opcoes": ["Sanável e sem prejuízo a terceiros", "De finalidade, por desvio de poder", "De motivo inexistente", "De objeto ilícito"], "explicacao": "Art. 55 da Lei 9.784/1999."}, {"id": 10358, "materia": "adm", "nivel": 4, "enunciado": "Pela Lei 9.784/1999, o recurso administrativo tramita, em regra, por no máximo:", "opcoes": ["Três instâncias", "Duas instâncias", "Cinco instâncias", "Uma instância"], "explicacao": "Art. 57 da Lei 9.784/1999."}, {"id": 10359, "materia": "const", "nivel": 4, "enunciado": "A reunião pacífica, sem armas, em locais abertos ao público:", "opcoes": ["Independe de autorização, bastando aviso prévio à autoridade", "Depende de autorização prévia da polícia militar", "É proibida no período noturno, em qualquer caso", "Exige licença do município com 30 dias de antecedência, no mínimo"], "explicacao": "Art. 5º, XVI, da CF."}, {"id": 10360, "materia": "const", "nivel": 4, "enunciado": "União, estados e DF legislam concorrentemente sobre:", "opcoes": ["Direito penitenciário", "Direito penal", "Direito processual", "Direito eleitoral"], "explicacao": "Art. 24, I, da CF."}, {"id": 10361, "materia": "const", "nivel": 4, "enunciado": "O policial militar que comete crime doloso contra a vida de civil é julgado pelo:", "opcoes": ["Tribunal do Júri", "Justiça Militar estadual", "Justiça Federal", "Superior Tribunal Militar"], "explicacao": "Art. 125, § 4º, da CF."}, {"id": 10362, "materia": "const", "nivel": 4, "enunciado": "Compete à Justiça Federal julgar:", "opcoes": ["Crimes políticos e infrações contra bens ou interesses da União", "Todos os crimes de tráfico de drogas, inclusive o tráfico local", "Os crimes dolosos contra a vida cometidos por servidores", "As contravenções penais contra bens da União"], "explicacao": "Art. 109, IV, da CF."}, {"id": 10363, "materia": "const", "nivel": 4, "enunciado": "As contravenções penais, ainda que atinjam interesse da União, são julgadas pela:", "opcoes": ["Justiça Estadual", "Justiça Federal", "Justiça Militar", "Justiça Eleitoral"], "explicacao": "Art. 109, IV, da CF e Súmula 38 do STJ."}, {"id": 10364, "materia": "const", "nivel": 4, "enunciado": "A Constituição considera inafiançáveis e insuscetíveis de graça ou anistia:", "opcoes": ["Tortura, tráfico, terrorismo e crimes hediondos", "O racismo e a ação de grupos armados contra o Estado", "Todos os crimes dolosos contra a vida", "Os crimes de responsabilidade"], "explicacao": "Art. 5º, XLIII, da CF. O racismo e a ação de grupos armados são inafiançáveis e imprescritíveis."}, {"id": 10365, "materia": "const", "nivel": 4, "enunciado": "São imprescritíveis, pela Constituição:", "opcoes": ["O racismo e a ação de grupos armados contra a ordem constitucional", "A tortura, o tráfico ilícito de entorpecentes e o terrorismo internacional", "Os crimes hediondos e o terrorismo", "O homicídio qualificado e o latrocínio"], "explicacao": "Art. 5º, XLII e XLIV, da CF."}, {"id": 10366, "materia": "const", "nivel": 4, "enunciado": "O incidente de deslocamento de competência para a Justiça Federal, em grave violação de direitos humanos, é suscitado:", "opcoes": ["O Procurador-Geral da República, perante o STJ", "Pelo governador do estado, perante o STF", "Pelo Ministro da Justiça, perante o STJ", "O Defensor Público-Geral Federal, perante o STF"], "explicacao": "Art. 109, § 5º, da CF."}, {"id": 10367, "materia": "const", "nivel": 4, "enunciado": "Pela Constituição, a polícia rodoviária federal é órgão:", "opcoes": ["Permanente, mantido pela União e estruturado em carreira", "Temporário, mantido pelos estados e municípios, sem carreira própria", "Subordinado ao Exército", "Vinculado aos municípios"], "explicacao": "Art. 144, § 2º, da CF."}, {"id": 10368, "materia": "const", "nivel": 4, "enunciado": "A intervenção federal num estado por desobediência a ordem judicial depende de:", "opcoes": ["Requisição do STF, STJ ou TSE", "Pedido do governador do estado", "Decisão do Senado", "Plebiscito"], "explicacao": "Art. 36, II, da CF."}, {"id": 10369, "materia": "dh", "nivel": 4, "enunciado": "No Brasil, o direito do detido de pedir a um juiz que decida sobre a legalidade da prisão corresponde ao:", "opcoes": ["Habeas corpus", "Habeas data", "Mandado de injunção", "Recurso especial"], "explicacao": "Art. 7.6 da Convenção Americana e art. 5º, LXVIII, da CF."}, {"id": 10370, "materia": "dh", "nivel": 4, "enunciado": "O Tribunal Penal Internacional julga, entre outros, os crimes de:", "opcoes": ["Genocídio, contra a humanidade, de guerra e de agressão", "Tráfico internacional de drogas e lavagem de dinheiro sujo", "Terrorismo doméstico e corrupção de autoridades", "Homicídio comum e roubo à mão armada"], "explicacao": "Art. 5º do Estatuto de Roma."}, {"id": 10371, "materia": "dh", "nivel": 4, "enunciado": "Pela Constituição, o Brasil se submete à jurisdição do:", "opcoes": ["Tribunal Penal Internacional, a cuja criação aderiu", "Conselho de Segurança da ONU, em qualquer matéria penal", "Tribunal de Nuremberg, para crimes de guerra", "Tribunal de Haia em matéria tributária"], "explicacao": "Art. 5º, § 4º, da CF."}, {"id": 10372, "materia": "dh", "nivel": 4, "enunciado": "Para a Corte Interamericana, leis de anistia que impedem investigar graves violações de direitos humanos:", "opcoes": ["Não têm efeitos jurídicos", "São plenamente válidas", "Valem só para civis", "Dependem de referendo"], "explicacao": "Caso Gomes Lund vs. Brasil."}, {"id": 10373, "materia": "dh", "nivel": 4, "enunciado": "Pela Convenção Americana, o direito de resposta cabe a quem for atingido por:", "opcoes": ["Informações inexatas ou ofensivas veiculadas na imprensa", "Decisões judiciais desfavoráveis em processos criminais", "Multas de trânsito aplicadas por agentes públicos", "Leis aprovadas pelo Congresso que restrinjam direitos individuais"], "explicacao": "Art. 14 da Convenção Americana."}, {"id": 10374, "materia": "igual", "nivel": 4, "enunciado": "Aos remanescentes das comunidades de quilombos que ocupam suas terras é reconhecida:", "opcoes": ["A propriedade definitiva dessas terras", "A isenção de todos os tributos federais", "A reserva de cargos eletivos", "Uma indenização mensal em dinheiro"], "explicacao": "Art. 68 do ADCT e art. 31 do Estatuto da Igualdade Racial."}, {"id": 10375, "materia": "igual", "nivel": 4, "enunciado": "No Estatuto da Igualdade Racial, o Sinapir é o:", "opcoes": ["Sistema Nacional de Promoção da Igualdade Racial", "Sistema de Informações Penitenciárias do Ministério", "Serviço de Inteligência da Polícia Federal", "Sindicato Nacional dos Policiais"], "explicacao": "Art. 47 da Lei 12.288/2010."}, {"id": 10376, "materia": "igual", "nivel": 4, "enunciado": "No HC 154.248 (2021), o STF decidiu que a injúria racial:", "opcoes": ["É imprescritível, por ser espécie de racismo", "Prescreve como a injúria simples, em prazo menor", "É crime de ação penal privada", "É contravenção penal"], "explicacao": "Antes mesmo da Lei 14.532/2023."}, {"id": 10377, "materia": "inf", "nivel": 4, "enunciado": "Na criptografia assimétrica, para mandar uma mensagem sigilosa, cifra-se com a chave:", "opcoes": ["Pública do destinatário", "Privada do destinatário", "Privada do remetente", "Pública do remetente"], "explicacao": "Só a chave privada do destinatário abre."}, {"id": 10378, "materia": "inf", "nivel": 4, "enunciado": "Na assinatura digital, o remetente assina com a chave:", "opcoes": ["Privada dele", "Pública dele", "Pública do destinatário", "Privada do destinatário"], "explicacao": "Quem recebe confere com a chave pública do remetente."}, {"id": 10379, "materia": "inf", "nivel": 4, "enunciado": "Um endereço IPv4 tem:", "opcoes": ["32 bits", "64 bits", "128 bits", "16 bits"], "explicacao": "Quatro blocos de 8 bits."}, {"id": 10380, "materia": "inf", "nivel": 4, "enunciado": "Um endereço IPv6 tem:", "opcoes": ["128 bits", "64 bits", "32 bits", "256 bits"], "explicacao": "Oito blocos de 16 bits."}, {"id": 10381, "materia": "inf", "nivel": 4, "enunciado": "O golpe em que o criminoso liga fingindo ser do banco para obter dados chama-se:", "opcoes": ["Vishing", "Smishing", "Pharming", "Spoofing"], "explicacao": "Phishing por voz. Por SMS, é smishing."}, {"id": 10382, "materia": "leg", "nivel": 4, "enunciado": "Na Lei de Drogas, a pena do tráfico aumenta de 1/6 a 2/3 se o crime envolver ou visar atingir:", "opcoes": ["Criança ou adolescente", "Pessoa maior de 60 anos", "Estrangeiro em situação regular", "Servidor público aposentado"], "explicacao": "Art. 40, VI, da Lei 11.343/2006."}, {"id": 10383, "materia": "leg", "nivel": 4, "enunciado": "Na Lei de Drogas, quem colabora voluntariamente identificando coautores e ajudando a recuperar o produto do crime tem a pena:", "opcoes": ["Reduzida de um terço a dois terços", "Extinta", "Reduzida pela metade", "Convertida em multa e serviços"], "explicacao": "Art. 41 da Lei 11.343/2006."}, {"id": 10384, "materia": "leg", "nivel": 4, "enunciado": "Pelo ECA, o adolescente apreendido por ordem judicial deve ser, desde logo:", "opcoes": ["Encaminhado à autoridade judiciária", "Levado a uma delegacia comum para depor", "Entregue aos pais sem registro", "Internado por 45 dias"], "explicacao": "Art. 171 do ECA."}, {"id": 10385, "materia": "leg", "nivel": 4, "enunciado": "Pelo ECA, a internação antes da sentença pode durar no máximo:", "opcoes": ["45 dias", "30 dias", "90 dias", "60 dias"], "explicacao": "Art. 108 do ECA."}, {"id": 10386, "materia": "leg", "nivel": 4, "enunciado": "Pelo ECA, a medida de semiliberdade:", "opcoes": ["Não tem prazo fixo e segue as regras da internação", "Tem prazo fixo de 6 meses, sem prorrogação", "Dura no máximo 1 ano, renovável uma vez", "Só pode ser aplicada a crianças de 10 a 12 anos de idade"], "explicacao": "Art. 120, § 2º, do ECA."}, {"id": 10387, "materia": "leg", "nivel": 4, "enunciado": "O crime de violência psicológica contra a mulher (art. 147-B do CP) tem pena de:", "opcoes": ["Reclusão de 6 meses a 2 anos e multa", "Detenção de 1 a 3 anos e multa, apenas", "Reclusão de 2 a 5 anos e multa", "Detenção de 3 meses a 1 ano"], "explicacao": "Incluído pela Lei 14.188/2021."}, {"id": 10388, "materia": "leg", "nivel": 4, "enunciado": "O crime de perseguição (stalking), art. 147-A do CP, tem pena de:", "opcoes": ["Reclusão de 6 meses a 2 anos e multa", "Detenção de 1 a 6 meses ou multa", "Reclusão de 1 a 4 anos e multa, apenas", "Detenção de 3 meses a 1 ano"], "explicacao": "Incluído pela Lei 14.132/2021."}, {"id": 10389, "materia": "leg", "nivel": 4, "enunciado": "Os crimes do Estatuto da Pessoa Idosa são de ação penal:", "opcoes": ["Pública incondicionada", "Privada", "Pública condicionada", "Privada personalíssima"], "explicacao": "Art. 95 da Lei 10.741/2003."}, {"id": 10390, "materia": "leg", "nivel": 4, "enunciado": "Pelo Estatuto da Pessoa Idosa, aos crimes nele previstos com pena máxima de até 4 anos aplica-se o procedimento:", "opcoes": ["Da Lei 9.099/1995", "Do Tribunal do Júri", "Ordinário, sempre", "Do ECA"], "explicacao": "Art. 94 da Lei 10.741/2003."}, {"id": 10391, "materia": "leg", "nivel": 4, "enunciado": "Matar animal da fauna silvestre sem autorização tem pena de:", "opcoes": ["Detenção de 6 meses a 1 ano e multa", "Reclusão de 2 a 5 anos e multa, apenas", "Detenção de 1 a 3 anos e multa", "Apenas multa administrativa"], "explicacao": "Art. 29 da Lei 9.605/1998."}, {"id": 10392, "materia": "leg", "nivel": 4, "enunciado": "Na Lei de Crimes Ambientais, a pessoa jurídica pode ser responsabilizada:", "opcoes": ["Administrativa, civil e penalmente", "Apenas na esfera civil", "Apenas na esfera administrativa", "Penalmente, só se o diretor for condenado"], "explicacao": "Art. 3º da Lei 9.605/1998 e art. 225, § 3º, da CF."}, {"id": 10393, "materia": "leg", "nivel": 4, "enunciado": "Pela Lei de Abuso de Autoridade, os efeitos de perda do cargo e de inabilitação dependem de:", "opcoes": ["Reincidência em abuso e declaração motivada na sentença", "Simples condenação por qualquer crime previsto na lei, sem mais", "Pedido da vítima ao juiz", "Decisão administrativa do chefe"], "explicacao": "Art. 4º, parágrafo único, da Lei 13.869/2019."}, {"id": 10394, "materia": "leg", "nivel": 4, "enunciado": "Pela Lei 9.613/1998, a pena da lavagem aumenta de 1/3 a 2/3 se o crime for cometido:", "opcoes": ["De forma reiterada ou por organização criminosa", "Por réu primário com bons antecedentes e emprego", "Em valor baixo", "Sem violência"], "explicacao": "Art. 1º, § 4º, da Lei 9.613/1998."}, {"id": 10395, "materia": "ml", "nivel": 4, "enunciado": "A lei de Nysten descreve a ordem de instalação da:", "opcoes": ["Rigidez cadavérica", "Putrefação", "Mancha verde", "Saponificação"], "explicacao": "Da cabeça para os pés."}, {"id": 10396, "materia": "ml", "nivel": 4, "enunciado": "As manchas de Tardieu (petéquias) são vistas com frequência em mortes por:", "opcoes": ["Asfixia", "Arma branca", "Queda", "Hipotermia"], "explicacao": "Pequenas hemorragias em pleuras e pericárdio."}, {"id": 10397, "materia": "ml", "nivel": 4, "enunciado": "Na intoxicação por monóxido de carbono, os livores costumam ter cor:", "opcoes": ["Vermelho-carmim", "Azul-escura", "Esverdeada", "Amarelada"], "explicacao": "Pela carboxiemoglobina."}, {"id": 10398, "materia": "ml", "nivel": 4, "enunciado": "Na odontologia legal, a identificação é feita comparando o exame do cadáver com:", "opcoes": ["Registros odontológicos feitos em vida", "Fotografias de família tiradas em festas", "Impressões digitais registradas na carteira de identidade", "Exames de sangue de rotina antigos"], "explicacao": "Registros odontológicos ante mortem."}, {"id": 10399, "materia": "ml", "nivel": 4, "enunciado": "O espasmo cadavérico (rigidez instantânea) ocorre:", "opcoes": ["No momento da morte, sem relaxamento prévio", "Somente 24 horas depois da morte, nos membros", "Apenas em corpos de afogados", "Depois do início da putrefação"], "explicacao": "Ex.: arma presa na mão do suicida."}, {"id": 10400, "materia": "ml", "nivel": 4, "enunciado": "Pela Lei 12.037/2009, a identificação criminal inclui os processos:", "opcoes": ["Datiloscópico e fotográfico", "Fotográfico e de assinatura", "Genético, sempre obrigatório", "De voz e de escrita"], "explicacao": "Art. 5º da Lei 12.037/2009."}, {"id": 10401, "materia": "ml", "nivel": 4, "enunciado": "A tatuagem e o esfumaçamento ao redor da entrada do projétil ajudam a estimar:", "opcoes": ["A distância do disparo", "O calibre exato da arma", "A hora da morte", "A idade do atirador"], "explicacao": "Indicam tiro a curta distância."}, {"id": 10402, "materia": "pcd", "nivel": 4, "enunciado": "Na LBI, a pena da discriminação aumenta de um terço quando a vítima:", "opcoes": ["Está sob cuidado e responsabilidade do agente", "É maior de 18 anos", "Mora em outro município", "Tem deficiência apenas temporária ou parcial, comprovada"], "explicacao": "Art. 88, § 1º, da LBI."}, {"id": 10403, "materia": "pcd", "nivel": 4, "enunciado": "Se a discriminação da LBI é cometida pelos meios de comunicação, a pena é de:", "opcoes": ["Reclusão de 2 a 5 anos e multa", "Reclusão de 1 a 3 anos e multa", "Detenção de 1 a 2 anos", "Apenas multa"], "explicacao": "Art. 88, § 2º, da LBI."}, {"id": 10404, "materia": "pcd", "nivel": 4, "enunciado": "Pela LBI, reter ou usar cartão magnético ou documento de pessoa com deficiência para obter vantagem tem pena de:", "opcoes": ["Detenção de 6 meses a 2 anos e multa", "Reclusão de 2 a 5 anos e multa, apenas", "Detenção de 1 a 3 meses", "Apenas multa"], "explicacao": "Art. 91 da LBI."}, {"id": 10405, "materia": "pen", "nivel": 4, "enunciado": "No crime impossível, por ineficácia absoluta do meio ou impropriedade absoluta do objeto:", "opcoes": ["Não se pune a tentativa", "Pune-se a tentativa com pena reduzida", "O crime se consuma com pena menor", "O agente responde por crime culposo"], "explicacao": "Art. 17 do CP."}, {"id": 10406, "materia": "pen", "nivel": 4, "enunciado": "Pelo Código Penal, quem de qualquer modo concorre para o crime responde pelas penas a ele cominadas:", "opcoes": ["Na medida de sua culpabilidade", "Sempre com a mesma pena do autor", "Com a pena reduzida pela metade", "Só se tiver praticado o verbo do tipo"], "explicacao": "Art. 29 do CP."}, {"id": 10407, "materia": "pen", "nivel": 4, "enunciado": "Se um dos concorrentes quis participar de crime menos grave, recebe:", "opcoes": ["A pena deste, aumentada até a metade se o mais grave era previsível", "A pena do crime mais grave cometido pelos demais concorrentes", "Isenção total de pena, por falta de dolo em relação ao crime maior", "A pena do crime mais grave, reduzida de um terço"], "explicacao": "Art. 29, § 2º, do CP."}, {"id": 10408, "materia": "pen", "nivel": 4, "enunciado": "A participação de menor importância permite:", "opcoes": ["Diminuir a pena de um sexto a um terço", "Isentar o partícipe de pena", "Reduzir a pena pela metade", "Substituir a pena por multa, obrigatoriamente"], "explicacao": "Art. 29, § 1º, do CP."}, {"id": 10409, "materia": "pen", "nivel": 4, "enunciado": "As circunstâncias e condições de caráter pessoal não se comunicam entre os concorrentes, salvo:", "opcoes": ["Quando elementares do crime", "Quando favoráveis ao réu e ao partícipe", "Nos crimes hediondos", "Nos crimes culposos"], "explicacao": "Art. 30 do CP."}, {"id": 10410, "materia": "pen", "nivel": 4, "enunciado": "O crime de concussão se consuma com:", "opcoes": ["A simples exigência da vantagem", "O recebimento efetivo da vantagem", "O prejuízo efetivo da vítima", "A denúncia formal do servidor"], "explicacao": "É crime formal: basta a exigência."}, {"id": 10411, "materia": "pen", "nivel": 4, "enunciado": "A pena da corrupção passiva é aumentada de um terço se, em razão da vantagem, o servidor:", "opcoes": ["Retarda ou omite ato de ofício, ou o pratica violando dever", "Apenas solicita a vantagem, sem chegar a recebê-la nem pedir de novo", "Pratica o ato de ofício estritamente dentro da lei", "Devolve a vantagem antes de praticar qualquer ato"], "explicacao": "Art. 317, § 1º, do CP."}, {"id": 10412, "materia": "pen", "nivel": 4, "enunciado": "Comete tráfico de influência quem:", "opcoes": ["Solicita vantagem a pretexto de influir em ato de servidor", "Oferece vantagem a servidor para que pratique um ato", "Exige vantagem indevida em razão da própria função", "Usa informação sigilosa do cargo em benefício próprio ou de parente"], "explicacao": "Art. 332 do CP."}, {"id": 10413, "materia": "pen", "nivel": 4, "enunciado": "Se da extorsão mediante sequestro resulta morte, a pena é de reclusão de:", "opcoes": ["24 a 30 anos", "20 a 30 anos", "12 a 30 anos", "16 a 24 anos"], "explicacao": "Art. 159, § 3º, do CP."}, {"id": 10414, "materia": "pen", "nivel": 4, "enunciado": "Na extorsão mediante sequestro em concurso, o concorrente que denuncia o crime e facilita a libertação da vítima tem a pena:", "opcoes": ["Reduzida de um a dois terços", "Extinta", "Reduzida pela metade", "Substituída por multa e serviços"], "explicacao": "Art. 159, § 4º, do CP."}, {"id": 10415, "materia": "pen", "nivel": 4, "enunciado": "A sentença que concede o perdão judicial:", "opcoes": ["Não é considerada para efeito de reincidência", "Gera reincidência em qualquer caso", "Equivale a condenação para fins de maus antecedentes", "Deve ser cumprida em regime aberto"], "explicacao": "Art. 120 do CP e Súmula 18 do STJ."}, {"id": 10416, "materia": "pen", "nivel": 4, "enunciado": "Na receptação culposa, se o criminoso é primário, o juiz pode:", "opcoes": ["Deixar de aplicar a pena, conforme o caso", "Apenas reduzir a pena pela metade, sem perdão", "Substituir a pena por prisão domiciliar", "Aplicar a pena do crime doloso"], "explicacao": "Art. 180, § 5º, do CP."}, {"id": 10417, "materia": "pen", "nivel": 4, "enunciado": "A extinção da punibilidade do crime antecedente impede a punição da receptação?", "opcoes": ["Não, a receptação é punível mesmo assim", "Sim, sempre", "Sim, se o autor do crime anterior morrer", "Só se houver perdão da vítima"], "explicacao": "Art. 180, § 4º, do CP."}, {"id": 10418, "materia": "pen", "nivel": 4, "enunciado": "No roubo, se da violência resulta lesão corporal grave, a pena é de reclusão de:", "opcoes": ["7 a 18 anos e multa", "4 a 10 anos e multa", "20 a 30 anos e multa", "5 a 15 anos e multa"], "explicacao": "Art. 157, § 3º, I, do CP."}, {"id": 10419, "materia": "pen", "nivel": 4, "enunciado": "No latrocínio, a pena é de reclusão de:", "opcoes": ["20 a 30 anos e multa", "12 a 30 anos e multa", "24 a 30 anos e multa", "15 a 25 anos e multa"], "explicacao": "Art. 157, § 3º, II, do CP."}, {"id": 10420, "materia": "port", "nivel": 4, "enunciado": "Assinale a frase correta quanto à concordância:", "opcoes": ["Seguem anexas as cópias.", "Segue anexo as cópias.", "Seguem anexo as cópias.", "Segue anexas as cópias."], "explicacao": "“Anexo” é adjetivo e concorda com o substantivo; o verbo concorda com o sujeito."}, {"id": 10421, "materia": "port", "nivel": 4, "enunciado": "Assinale a frase correta:", "opcoes": ["É proibida a entrada de estranhos.", "É proibido a entrada de estranhos.", "É proibida entrada de estranhos.", "São proibidas a entrada de estranhos."], "explicacao": "Com artigo, o adjetivo concorda (proibida a entrada); sem artigo, fica invariável (proibido entrada)."}, {"id": 10422, "materia": "port", "nivel": 4, "enunciado": "Assinale a forma correta:", "opcoes": ["Meio-dia e meia.", "Meio-dia e meio.", "Meio dia e meio.", "Meia-dia e meia."], "explicacao": "Meio-dia e meia (hora)."}, {"id": 10423, "materia": "port", "nivel": 4, "enunciado": "Assinale a regência correta do verbo “implicar” no sentido de “acarretar”:", "opcoes": ["A falta implica punição.", "A falta implica em punição.", "A falta implica na punição.", "A falta implica para punição."], "explicacao": "Na norma-padrão, “implicar” (acarretar) é transitivo direto."}, {"id": 10424, "materia": "port", "nivel": 4, "enunciado": "Assinale a regência correta do verbo “obedecer”:", "opcoes": ["Os agentes obedecem às normas.", "Os agentes obedecem as normas.", "Os agentes obedecem com as normas.", "Os agentes obedecem nas normas."], "explicacao": "Obedecer a algo: transitivo indireto."}, {"id": 10425, "materia": "port", "nivel": 4, "enunciado": "Em “Quanto mais se investiga, mais provas surgem”, a relação é de:", "opcoes": ["Proporção", "Concessão", "Finalidade", "Condição"], "explicacao": "“Quanto mais... mais” indica proporção."}, {"id": 10426, "materia": "ppen", "nivel": 4, "enunciado": "A cadeia de custódia começa:", "opcoes": ["Com a preservação do local ou a detecção do vestígio", "Com a entrega do laudo pericial ao juiz", "Com o oferecimento da denúncia pelo Ministério Público", "Com a prisão em flagrante do suspeito"], "explicacao": "Art. 158-A, § 1º, do CPP."}, {"id": 10427, "materia": "ppen", "nivel": 4, "enunciado": "Pelo CPP, a coleta dos vestígios deve ser feita preferencialmente por:", "opcoes": ["Perito oficial", "Policial militar", "Delegado de polícia", "Qualquer agente presente"], "explicacao": "Art. 158-C do CPP."}, {"id": 10428, "materia": "ppen", "nivel": 4, "enunciado": "A etapa da cadeia de custódia que consiste em distinguir um elemento como de potencial interesse para a perícia é o:", "opcoes": ["Reconhecimento", "Isolamento", "Acondicionamento", "Processamento"], "explicacao": "Art. 158-B, I, do CPP."}, {"id": 10429, "materia": "ppen", "nivel": 4, "enunciado": "A descrição detalhada do vestígio como foi encontrado, com fotografias e croquis, é a etapa de:", "opcoes": ["Fixação", "Reconhecimento", "Isolamento", "Acondicionamento"], "explicacao": "Art. 158-B, III, do CPP."}, {"id": 10430, "materia": "ppen", "nivel": 4, "enunciado": "O acordo de não persecução penal não se aplica, entre outros casos:", "opcoes": ["Aos crimes de violência doméstica contra a mulher", "Aos crimes contra o patrimônio sem violência", "Aos investigados primários e com bons antecedentes", "Aos crimes com pena mínima de 1 ano de reclusão"], "explicacao": "Art. 28-A, § 2º, IV, do CPP."}, {"id": 10431, "materia": "ppen", "nivel": 4, "enunciado": "Se o réu descumpre medida cautelar diversa da prisão, o juiz pode:", "opcoes": ["Substituí-la, somar outra medida ou decretar a preventiva", "Arquivar o processo e soltar o réu em caráter definitivo, sem medidas", "Absolver o réu por falta de interesse processual", "Aplicar multa ao advogado de defesa do réu"], "explicacao": "Art. 282, § 4º, do CPP."}, {"id": 10432, "materia": "ppen", "nivel": 4, "enunciado": "A prisão preventiva não pode ser decretada com a finalidade de:", "opcoes": ["Antecipar o cumprimento da pena", "Garantir a ordem pública", "Proteger a instrução criminal", "Assegurar a aplicação da lei penal"], "explicacao": "Art. 313, § 2º, do CPP."}, {"id": 10433, "materia": "ppen", "nivel": 4, "enunciado": "Pelo CPP, não se considera fundamentada a decisão que:", "opcoes": ["Usa motivos que serviriam para qualquer outra decisão", "Cita expressamente o artigo de lei que está sendo aplicado ao caso", "Analisa as provas concretas produzidas no processo", "Responde aos argumentos apresentados pelas partes"], "explicacao": "Art. 315, § 2º, III, do CPP."}, {"id": 10434, "materia": "ppen", "nivel": 4, "enunciado": "A competência por prevenção se dá quando, entre juízes igualmente competentes, um deles:", "opcoes": ["Antecede os outros na prática de algum ato do processo", "Tem mais tempo de carreira na magistratura estadual", "Atua na capital do estado", "Recebe o processo por sorteio eletrônico entre as varas"], "explicacao": "Art. 83 do CPP."}, {"id": 10435, "materia": "ppen", "nivel": 4, "enunciado": "Em regra, a competência no processo penal é do lugar:", "opcoes": ["Em que se consumar a infração", "Do domicílio do réu", "Do domicílio da vítima do crime", "Em que foi feito o inquérito"], "explicacao": "Art. 70 do CPP."}, {"id": 10436, "materia": "ppen", "nivel": 4, "enunciado": "No concurso entre a jurisdição comum e a do júri, prevalece:", "opcoes": ["A competência do júri", "A jurisdição comum", "A do juiz mais antigo", "A do domicílio do réu"], "explicacao": "Art. 78, I, do CPP."}, {"id": 10437, "materia": "ppen", "nivel": 4, "enunciado": "O interrogatório do réu preso por videoconferência é:", "opcoes": ["Excepcional, por decisão fundamentada, nos casos da lei", "A regra geral em todos os processos criminais", "Proibido em qualquer hipótese pela Constituição", "Livre, a critério do delegado que preside o caso no inquérito"], "explicacao": "Art. 185, § 2º, do CPP."}, {"id": 10438, "materia": "ppen", "nivel": 4, "enunciado": "Pelo CPP, a prisão preventiva pode ser decretada, independentemente da pena, quando houver dúvida sobre a identidade civil da pessoa e:", "opcoes": ["Ela não der elementos para esclarecê-la", "Ela for primária e de bons antecedentes, com emprego fixo", "O crime for culposo", "A vítima concordar"], "explicacao": "Art. 313, § 1º, do CPP."}, {"id": 10439, "materia": "ppen", "nivel": 4, "enunciado": "Para o STJ, o reconhecimento pessoal feito sem observar o art. 226 do CPP:", "opcoes": ["Não basta, sozinho, para fundamentar condenação", "É válido como prova plena em qualquer caso, se assinado", "Só é nulo se a defesa protestar na hora", "Vale se o delegado assinar o termo"], "explicacao": "HC 598.886/SC (2020)."}, {"id": 10440, "materia": "rl", "nivel": 4, "enunciado": "R$ 1.000 a juros compostos de 10% ao mês, por 2 meses, geram montante de:", "opcoes": ["R$ 1.210", "R$ 1.200", "R$ 1.100", "R$ 1.221"], "explicacao": "1.000 × 1,1² = 1.210."}, {"id": 10441, "materia": "rl", "nivel": 4, "enunciado": "A negação de “Todos os agentes são pontuais e nenhum falta” é:", "opcoes": ["Algum agente não é pontual ou algum agente falta", "Nenhum agente é pontual e todos os agentes faltam", "Algum agente não é pontual e algum agente falta", "Todos os agentes faltam ou não são pontuais"], "explicacao": "¬(P ∧ Q) = ¬P ∨ ¬Q."}, {"id": 10442, "materia": "rl", "nivel": 4, "enunciado": "Uma urna tem 3 bolas brancas e 2 pretas. Retirando 2 sem reposição, a probabilidade de ambas serem brancas é:", "opcoes": ["3/10", "9/25", "2/5", "1/2"], "explicacao": "3/5 × 2/4 = 6/20 = 3/10."}, {"id": 10443, "materia": "rl", "nivel": 4, "enunciado": "Se P é verdadeira e Q é falsa, o valor lógico de (P ∧ Q) ↔ ¬P é:", "opcoes": ["Verdadeiro", "Falso", "Indeterminado", "Depende de outra proposição"], "explicacao": "P ∧ Q é falso e ¬P é falso; F ↔ F é verdadeiro."}, {"id": 10444, "materia": "rl", "nivel": 4, "enunciado": "Ari, Bel e Caio são escrivão, investigador e delegado, não necessariamente nessa ordem. Ari não é delegado e Caio é escrivão. Logo, Bel é:", "opcoes": ["Delegado", "Investigador", "Escrivão", "Impossível saber"], "explicacao": "Caio é escrivão; Ari não é delegado, então é investigador; sobra delegado para Bel."}, {"id": 10445, "materia": "rl", "nivel": 4, "enunciado": "Três peritos fazem 12 laudos em 4 dias. Quantos laudos 5 peritos fazem em 6 dias, no mesmo ritmo?", "opcoes": ["30", "20", "24", "36"], "explicacao": "Cada perito faz 1 laudo por dia: 5 × 6 = 30."}, {"id": 10446, "materia": "rl", "nivel": 4, "enunciado": "Se nenhum corrupto é honesto e algum servidor é honesto, então necessariamente:", "opcoes": ["Algum servidor não é corrupto", "Nenhum servidor é corrupto", "Todo servidor é honesto", "Algum corrupto é servidor"], "explicacao": "O servidor honesto não pode ser corrupto."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes where id < 1000000));
select nivel, count(*) as questoes_novas from public.questoes where id between 9947 and 10446 group by nivel order by nivel;
select public.questoes_versao() as nova_versao;
